    const user = app.auth.requireRole('customer', 'vendor', 'admin');
    if (!user) return;
    this.user = user;
    this.setState({ user });
    await this.load();
  }

  async load() {
    this.setState({ loading: true });
    const u = (this.user || this.state.user);
    const res = await this.orders.listDownloads(u.id, { q: this.state.query, page: this.state.page, pageSize: 8 });
    this.setState({
