      counts: {
        orders: this.db.findAll('orders', { filter: { customerId: u.id } }).total,
        wishlist: this.db.findAll('wishlist', { filter: { userId: u.id } }).total,
        reviews: this.db.findAll('reviews', { filter: { userId: u.id } }).total,
        following: this.db.findAll('follows', { filter: { userId: u.id } }).total,
      },
    });
  }

  nav() {
    const url = this.app.router.url;
    const c = this.state.counts;
    return [
      { key: 'accountOrders', label: 'Orders', count: c.orders },
      { key: 'accountDownloads', label: 'Downloads', count: this.state.meta ? this.state.meta.total : 0 },
      { key: 'accountWishlist', label: 'Wishlist', count: c.wishlist },
      { key: 'accountReviews', label: 'My reviews', count: c.reviews },
      { key: 'accountFollowing', label: 'Following', count: c.following },
      { key: 'accountProfile', label: 'Profile', count: 0 },
    ].map(n => {
      const active = n.key === 'accountDownloads';
      return {
        label: n.label,
        href: url(n.key),
        current: active ? 'page' : undefined,
        bg: active ? '#F2FAF7' : 'transparent',
        ink: active ? '#29483C' : '#595959',
        weight: active ? 600 : 500,
        count: n.count ? String(n.count) : '',
        badgeBg: active ? '#3A836B' : '#EDF0EE',
        badgeInk: active ? '#FFFFFF' : '#595959',
      };
    });
  }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, rows, meta, query, page } = this.state;
    const total = meta ? meta.total : 0;
    const pages = meta ? meta.totalPages : 1;

    return {
      accountNav: this.app ? this.nav() : [],
      browseHref: url('browse'),
      loading,
      query,
      countLine: loading ? 'Loading…'
        : total === 0 ? 'Nothing here yet'
        : total + (total === 1 ? ' resource' : ' resources') + ' — download as often as you like, forever',
      isEmpty: !loading && rows.length === 0,
      hasRows: !loading && rows.length > 0,
      emptyTitle: query ? 'No downloads match that search' : 'You have not downloaded anything yet',
      emptyBody: query
        ? 'Try a shorter search, or clear it to see everything you own.'
        : 'Resources you buy appear here permanently, and you can re-download them any number of times.',

      rows: rows.map(r => ({
        title: r.title,
        cover: r.cover,
        href: url('product', { id: r.productId }),
        meta: [r.fileType, r.pageCount ? r.pageCount + ' pages' : null, r.fileSizeMb ? r.fileSizeMb + ' MB' : null].filter(Boolean).join(' · '),
        purchased: new Date(r.purchasedAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
        reference: r.orderReference,
        available: r.available,
        unavailable: !r.available,
        downloadLabel: 'Download ' + r.title,
        onDownload: async () => {
          try {
            await this.orders.downloadUrl((this.user || this.state.user).id, r.productId);
            this.app.toast('Download started: ' + (r.fileName || r.title), 'success');
          } catch (err) {
            this.app.toast(this.app.readError(err).message, 'error');
          }
        },
      })),

      showPager: !loading && pages > 1,
      pageLabel: 'Page ' + page + ' of ' + pages,
      prevDisabled: page <= 1,
      nextDisabled: page >= pages,
      prevOpacity: page <= 1 ? 0.4 : 1,
      nextOpacity: page >= pages ? 0.4 : 1,
      onPrev: () => { if (page > 1) this.setState({ page: page - 1 }, () => this.load()); },
      onNext: () => { if (page < pages) this.setState({ page: page + 1 }, () => this.load()); },
      onSearch: e => {
        const v = e.target.value;
        clearTimeout(this._t);
        this.setState({ query: v, page: 1 });
        this._t = setTimeout(() => this.load(), 220);
      },
    };
  }
}

