  state = {
    loading: true, user: null, counts: {}, busy: false, saved: false,
    errors: {}, formError: '', pwErrors: {},
    values: { firstName: '', lastName: '', email: '', roleLabel: '', avatar: null },
    pw: { newPassword: '', confirmNew: '' },
  };

  async componentDidMount() {
    const [app, users, orders, db, validation] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/usersRepo.js'),
      __ulmImport('assets/js/repositories/ordersRepo.js'),
      __ulmImport('assets/js/db.js'),
      __ulmImport('assets/js/validation.js'),
    ]);
    await app.boot();
    this.app = app; this.users = users; this.orders = orders; this.db = db; this.validation = validation;
    const user = app.auth.requireRole('customer', 'vendor', 'admin');
    if (!user) return;
    const dl = await orders.listDownloads(user.id, { pageSize: 500 });
    this.setState({
      loading: false, user,
      values: {
        firstName: user.firstName || '', lastName: user.lastName || '',
        email: user.email || '', roleLabel: user.roleLabel || 'Classroom Teacher',
        avatar: user.avatar || null,
      },
      counts: {
        orders: db.findAll('orders', { filter: { customerId: user.id } }).total,
        downloads: dl.meta.total,
        wishlist: db.findAll('wishlist', { filter: { userId: user.id } }).total,
        reviews: db.findAll('reviews', { filter: { userId: user.id } }).total,
        following: db.findAll('follows', { filter: { userId: user.id } }).total,
      },
    });
  }

  nav() {
    const url = this.app.router.url;
    const c = this.state.counts;
    return [
      { key: 'accountOrders', label: 'Orders', count: c.orders },
      { key: 'accountDownloads', label: 'Downloads', count: c.downloads },
      { key: 'accountWishlist', label: 'Wishlist', count: c.wishlist },
      { key: 'accountReviews', label: 'My reviews', count: c.reviews },
      { key: 'accountFollowing', label: 'Following', count: c.following },
      { key: 'accountProfile', label: 'Profile', count: 0 },
    ].map(n => {
      const active = n.key === 'accountProfile';
      return {
        label: n.label, href: url(n.key),
        current: active ? 'page' : undefined,
        bg: active ? '#F2FAF7' : 'transparent',
        ink: active ? '#29483C' : '#595959',
        weight: active ? 600 : 500,
        count: n.count ? String(n.count) : '',
        badgeBg: active ? '#3A836B' : '#EDF0EE',
        badgeInk: active ? '#FFFFFF' : '#595959',
      };
    });
  }

  field(name) {
    const err = this.state.errors[name];
    const cap = name.charAt(0).toUpperCase() + name.slice(1);
    return {
      ['v' + cap]: this.state.values[name],
      [name + 'Error']: err || '',
      [name + 'Border']: err ? '#C0392B' : '#CAC4D0',
      [name + 'LabelColor']: err ? '#C0392B' : '#49454F',
      [name + 'Invalid']: err ? 'true' : 'false',
    };
  }

  pwField(name) {
    const err = this.state.pwErrors[name];
    const cap = name.charAt(0).toUpperCase() + name.slice(1);
    return {
      ['v' + cap]: this.state.pw[name],
      [name + 'Error']: err || '',
      [name + 'Border']: err ? '#C0392B' : '#CAC4D0',
      [name + 'LabelColor']: err ? '#C0392B' : '#49454F',
      [name + 'Invalid']: err ? 'true' : 'false',
    };
  }

  renderVals() {
    const { loading, user, busy, saved, formError, values, pwErrors } = this.state;
    const initials = ((values.firstName[0] || '') + (values.lastName[0] || '')).toUpperCase();

    return Object.assign({
      accountNav: this.app ? this.nav() : [],
      loading,
      ready: !loading && !!user,
      hasAvatar: !!values.avatar,
      noAvatar: !values.avatar,
      avatar: values.avatar,
      initials: initials || '?',
      roleOptions: ['Classroom Teacher', 'Homeschool Parent', 'Weekend School Coordinator', 'School Administrator', 'Tutor', 'Other Educator'].map(value => ({ value })),
      busy, saved,
      submitOpacity: busy ? 0.72 : 1,
      submitLabel: busy ? 'Saving…' : 'Save changes',
      hasError: !!formError,
      formError,
      pwHelp: pwErrors.newPassword || 'At least 8 characters, with a letter and a number.',
      pwHelpColor: pwErrors.newPassword ? '#C0392B' : '#49454F',

      accountFacts: user ? [
        { label: 'Account type', value: ({ customer: 'Customer', vendor: 'Vendor', admin: 'Administrator' })[user.role] || user.role },
        { label: 'Member since', value: new Date(user.joinedAt).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' }) },
        { label: 'Status', value: user.status === 'active' ? 'Active' : 'Suspended' },
      ] : [],

      onInput: e => {
        const { name, value } = e.target;
        this.setState(s => ({
          values: Object.assign({}, s.values, { [name]: value }),
          errors: Object.assign({}, s.errors, { [name]: null }),
          formError: '', saved: false,
        }));
      },
      onPwInput: e => {
        const { name, value } = e.target;
        this.setState(s => ({
          pw: Object.assign({}, s.pw, { [name]: value }),
          pwErrors: Object.assign({}, s.pwErrors, { [name]: null }),
        }));
      },
      onAvatar: async e => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const avatar = await this.db.fileToDataUrl(file);
        this.setState(s => ({ values: Object.assign({}, s.values, { avatar }), saved: false }));
      },
      onSubmit: async e => {
        e.preventDefault();
        if (this.state.busy) return;
        const r = this.validation.rules;
        const { valid, errors } = this.validation.validate(this.state.values, {
          firstName: [r.required(), r.maxLength(50)],
          lastName: [r.required(), r.maxLength(50)],
          email: [r.required(), r.email()],
        });
        if (!valid) {
          this.setState({ errors });
          const el = document.getElementById('ap-' + Object.keys(errors)[0]);
          if (el) el.focus();
          return;
        }
        this.setState({ busy: true, formError: '' });
        try {
          await this.users.updateUser((this.user || this.state.user).id, this.state.values);
          this.setState({ busy: false, saved: true });
          this.app.toast('Profile updated.', 'success');
        } catch (err) {
          const { message, fields } = this.app.readError(err);
          this.setState({ busy: false, formError: message, errors: fields || {} });
        }
      },
      onPassword: async e => {
        e.preventDefault();
        const r = this.validation.rules;
        const { valid, errors } = this.validation.validate(this.state.pw, {
          newPassword: [r.required(), r.password()],
          confirmNew: [r.required(), r.matches('newPassword', 'new password')],
        });
        if (!valid) { this.setState({ pwErrors: errors }); return; }
        await this.users.updateUser((this.user || this.state.user).id, { password: this.state.pw.newPassword });
        this.setState({ pw: { newPassword: '', confirmNew: '' }, pwErrors: {} });
        this.app.toast('Password updated.', 'success');
      },
      onSignOut: async () => {
        await this.app.auth.logout();
        this.app.router.go('landing');
      },
    }, this.field('firstName'), this.field('lastName'), this.field('email'),
       this.field('roleLabel'), this.pwField('newPassword'), this.pwField('confirmNew'));
  }
}

