    const total = meta ? meta.total : 0;
    const bodyLen = (values.body || '').length;

    return {
      accountNav: this.app ? this.nav() : [],
      downloadsHref: url('accountDownloads'),
      loading,
      countLine: loading ? 'Loading…' : total === 0 ? 'No reviews written yet' : total + (total === 1 ? ' review' : ' reviews') + ' written',
      isEmpty: !loading && rows.length === 0 && !formFor,
      hasRows: !loading && rows.length > 0,
      hasPending: !loading && pending.length > 0 && !formFor,

      pending: pending.map(p => ({
        title: p.title, cover: p.cover,
        href: url('product', { id: p.productId }),
        onWrite: () => this.setState({ formFor: p, values: { rating: 0, body: '' }, errors: {} }),
      })),

      formOpen: !!formFor,
      formTitle: formFor ? formFor.title : '',
      ratingButtons: [1, 2, 3, 4, 5].map(n => {
        const on = values.rating >= n;
        return {
          label: n + (n === 1 ? ' star' : ' stars'),
          pressed: values.rating === n ? 'true' : 'false',
          bg: on ? '#FFF9E8' : '#FFFFFF',
          border: on ? '#FFC107' : '#DCE7E1',
          ink: on ? '#FFC107' : '#D5DDD9',
          onPick: () => this.setState(s => ({ values: Object.assign({}, s.values, { rating: n }), errors: Object.assign({}, s.errors, { rating: null }) })),
        };
      }),
      ratingError: errors.rating || '',
      ratingLabelColor: errors.rating ? '#C0392B' : '#49454F',
      vBody: values.body,
      bodyBorder: errors.body ? '#C0392B' : '#CAC4D0',
      bodyLabelColor: errors.body ? '#C0392B' : '#49454F',
      bodyInvalid: errors.body ? 'true' : 'false',
      bodyHelp: errors.body || bodyLen + ' / 1000 characters — at least 20.',
      bodyHelpColor: errors.body ? '#C0392B' : '#49454F',
      busy,
      submitOpacity: busy ? 0.72 : 1,
      submitLabel: busy ? 'Publishing…' : 'Publish review',

      rows: rows.map(r => ({
        productTitle: r.productTitle, cover: r.productCover,
        href: url('product', { id: r.productId }),
        stars: this.stars(r.rating),
        body: r.body,
        date: new Date(r.createdAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
        deleteLabel: 'Delete your review of ' + r.productTitle,
        onDelete: async () => {
          const ok = await this.app.confirmDialog({
            title: 'Delete this review?',
            body: 'It will be removed from the product page and the rating recalculated.',
            confirmLabel: 'Delete review',
          });
          if (!ok) return;
          await this.reviews.deleteReview(r.id, (this.user || this.state.user));
          await this.load();
          this.app.toast('Review deleted.', 'success');
        },
      })),

      onInput: e => {
        const { name, value } = e.target;
        this.setState(s => ({
          values: Object.assign({}, s.values, { [name]: value }),
          errors: Object.assign({}, s.errors, { [name]: null }),
        }));
      },
      onCancel: () => this.setState({ formFor: null, errors: {}, values: { rating: 0, body: '' } }),
      onSubmit: async e => {
        e.preventDefault();
        if (this.state.busy) return;
        const { valid, errors: errs } = this.validation.validate(this.state.values, this.validation.schemas.review);
        if (!valid) { this.setState({ errors: errs }); return; }
        this.setState({ busy: true });
        try {
          await this.reviews.createReview(this.state.formFor.productId, (this.user || this.state.user), this.state.values);
          this.setState({ busy: false, formFor: null, values: { rating: 0, body: '' } });
          await this.load();
          this.app.toast('Thank you — your review has been published.', 'success');
        } catch (err) {
          this.setState({ busy: false });
          this.app.toast(this.app.readError(err).message, 'error');
        }
      },
    };
  }
}

