const BADGES = {
  approved: { bg: '#EAF7F1', ink: '#3A836B', label: 'LIVE' },
  pending: { bg: '#FFF2DE', ink: '#B9913E', label: 'IN REVIEW' },
  draft: { bg: '#E3F7FD', ink: '#2F7FA0', label: 'DRAFT' },
  declined: { bg: '#FDF1EF', ink: '#C0392B', label: 'DECLINED' },
  unpublished: { bg: '#F3F4F6', ink: '#595959', label: 'UNPUBLISHED' },
};

class Component extends DCLogic {
  state = { loading: true, rows: [], meta: null, counts: {}, vendors: [], user: null, status: '', vendorId: '', query: '', page: 1 };

  async componentDidMount() {
    const [app, products, vendorsRepo, db] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/productsRepo.js'),
      __ulmImport('assets/js/repositories/vendorsRepo.js'),
      __ulmImport('assets/js/db.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, products, vendorsRepo, db });
    const user = app.auth.requireRole('admin');
    if (!user) return;
    const vs = await vendorsRepo.listVendors({ pageSize: 60 });
    this.setState({
      user,
      vendors: vs.data,
      vendorId: app.router.param('vendor', '') || '',
    });
    await this.load();
  }

  async load() {
    const res = await this.products.listProducts({
      status: this.state.status || 'any',
      vendorId: this.state.vendorId || undefined,
      q: this.state.query,
      page: this.state.page, pageSize: 15,
      sort: 'newest',
    });
    const all = this.db.findAll('products').rows;
    this.setState({
      loading: false, rows: res.data, meta: res.meta,
      counts: {
        all: all.length,
        approved: all.filter(p => p.status === 'approved').length,
        pending: all.filter(p => p.status === 'pending').length,
        declined: all.filter(p => p.status === 'declined').length,
        unpublished: all.filter(p => p.status === 'unpublished').length,
      },
    });
  }

  set(patch) { this.setState(patch, () => this.load()); }

  stars(n) {
    const f = Math.round(Number(n) || 0);
    return '★'.repeat(f) + '☆'.repeat(Math.max(0, 5 - f));
  }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, rows, meta, counts, vendors, status, vendorId, query, page } = this.state;
    const pages = meta ? meta.totalPages : 1;

    return {
      subtitle: counts.all ? counts.all + ' resources across every vendor · ' + counts.approved + ' live' : '',
      loading, query, vendorId,
      vendorOptions: vendors.map(v => ({ id: v.id, name: v.storeName })),

      tabs: [
        { key: '', label: 'All', n: counts.all },
        { key: 'approved', label: 'Live', n: counts.approved },
        { key: 'pending', label: 'In review', n: counts.pending },
        { key: 'declined', label: 'Declined', n: counts.declined },
        { key: 'unpublished', label: 'Unpublished', n: counts.unpublished },
      ].map(t => {
        const on = t.key === status;
        return {
          label: t.label,
          count: String(t.n || 0),
          pressed: on ? 'true' : 'false',
          bg: on ? '#3A836B' : '#FFFFFF',
          border: on ? '#3A836B' : '#E7E9EE',
          ink: on ? '#FFFFFF' : '#29483C',
          pillBg: on ? 'rgba(255,255,255,.22)' : '#F1F3F6',
          pillInk: on ? '#FFFFFF' : '#595959',
          onPick: () => this.set({ status: t.key, page: 1 }),
        };
      }),

      isEmpty: !loading && rows.length === 0,
      hasRows: !loading && rows.length > 0,
      emptyTitle: query || status || vendorId ? 'Nothing matches that view' : 'The catalogue is empty',
      emptyBody: query || status || vendorId
        ? 'Try clearing the search, the vendor filter, or the status.'
        : 'Resources appear here once vendors submit them.',

      rows: rows.map(p => {
        const b = BADGES[p.status] || BADGES.draft;
        return {
          title: p.title.length > 60 ? p.title.slice(0, 58).trim() + '…' : p.title,
          cover: p.cover,
          href: url('product', { id: p.id }),
          vendorName: p.vendorName,
          meta: [p.categoryName, p.gradeLabel].filter(Boolean).join(' · '),
          badgeText: b.label, badgeBg: b.bg, badgeInk: b.ink,
          price: p.price ? '$' + p.price.toFixed(2) : 'Free',
          downloads: (p.downloads || 0).toLocaleString('en-US') + ' dl',
          stars: this.stars(p.ratingAvg),
          ratingLabel: p.ratingCount ? '(' + p.ratingCount + ')' : '(new)',
          canUnpublish: p.status === 'approved',
          canApprove: p.status === 'pending' || p.status === 'unpublished',
          deleteLabel: 'Delete ' + p.title,

          onUnpublish: async () => {
            const ok = await this.app.confirmDialog({
              title: 'Unpublish this resource?',
              body: '"' + p.title + '" will be removed from the storefront. Existing purchasers keep their download access.',
              confirmLabel: 'Unpublish',
            });
            if (!ok) return;
            await this.products.unpublishProduct(p.id);
            await this.load();
            this.app.toast('Product unpublished. It is no longer visible on the storefront.', 'info');
          },
          onApprove: async () => {
            await this.products.approveProduct(p.id, (this.user || this.state.user).id);
            await this.load();
            this.app.toast('Product approved and published to the storefront.', 'success');
          },
          onDelete: async () => {
            const ok = await this.app.confirmDialog({
              title: 'Delete this resource?',
              body: '"' + p.title + '" is removed permanently. Purchasers keep their download access.',
              confirmLabel: 'Delete resource',
            });
            if (!ok) return;
            await this.products.deleteProduct(p.id);
            await this.load();
            this.app.toast('Product deleted.', 'success');
          },
        };
      }),

      showPager: !loading && pages > 1,
      pageLabel: 'Page ' + page + ' of ' + pages,
      prevDisabled: page <= 1, nextDisabled: page >= pages,
      prevOpacity: page <= 1 ? 0.4 : 1, nextOpacity: page >= pages ? 0.4 : 1,
      onPrev: () => { if (page > 1) this.set({ page: page - 1 }); },
      onNext: () => { if (page < pages) this.set({ page: page + 1 }); },
      onVendor: e => this.set({ vendorId: e.target.value, page: 1 }),
      onSearch: e => {
        const v = e.target.value;
        clearTimeout(this._t);
        this.setState({ query: v, page: 1 });
        this._t = setTimeout(() => this.load(), 240);
      },
    };
  }
}

