      categories: (this.rules ? this.rules.CATEGORIES : []).map(c => {
        const n = this.db.findAll('products', { filter: { categoryId: c.id, status: 'approved' } }).total;
        return {
          name: c.name,
          tint: c.tint,
          href: url('browse', { category: c.slug }),
