  money(n) { return '$' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, stats: s, queues: q, launchMode } = this.state;
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const max = s && s.byMonth.length ? Math.max.apply(null, s.byMonth.map(m => m.gross)) : 0;
    const planMax = s && s.byPlan.length ? Math.max.apply(null, s.byPlan.map(p => p.vendors)) : 0;
    const fills = { free: '#C9C9C9', basic: '#9FD0BE', premium: '#3A836B', publishers: '#FEDC97' };

    const cards = [];
    if (q.vendors) cards.push({ count: String(q.vendors), label: 'Vendor registrations', note: 'Waiting for approval', href: url('adminVendorQueue'), bg: '#FFF9EF', accent: '#B9913E' });
    if (q.products) cards.push({ count: String(q.products), label: 'Product submissions', note: 'Waiting for review', href: url('adminProductQueue'), bg: '#FDF6F5', accent: '#C0392B' });
    if (q.payouts) cards.push({ count: String(q.payouts), label: 'Payout requests', note: 'Waiting to be processed', href: url('adminPayouts'), bg: '#F3FBFE', accent: '#2F7FA0' });
    if (q.messages) cards.push({ count: String(q.messages), label: 'Open buyer messages', note: 'Across all vendors', href: url('adminVendors'), bg: '#F7F4FD', accent: '#7A5FA8' });

    const isPre = launchMode === 'pre-launch';

    return {
      loading,
      ready: !loading && !!s,
      subtitle: s ? 'Every figure derived from ' + s.orderCount + ' completed orders' : '',
      payoutsHref: url('adminPayouts'),
      reportsHref: url('adminReports'),

      hasQueues: cards.length > 0,
      queueCards: cards,

      stats: s ? [
        { label: 'Gross sales', value: this.money(s.grossSales), note: s.orderCount + ' orders · AOV ' + this.money(s.averageOrderValue), mark: '$', tint: '#EAF7F1', ink: '#3A836B' },
        { label: 'Commission earned', value: this.money(s.commissionEarned), note: 'Platform revenue', mark: '%', tint: '#FFF2DE', ink: '#B9913E' },
        { label: 'Vendor earnings', value: this.money(s.vendorEarnings), note: this.money(s.transactionFees) + ' in fees', mark: '↑', tint: '#F2FAF7', ink: '#116254' },
        { label: 'Approved vendors', value: String(s.vendorCount), note: s.pendingVendors + ' awaiting approval', mark: '⌂', tint: '#E3F7FD', ink: '#2F7FA0' },
        { label: 'Live resources', value: String(s.productCount), note: s.pendingProducts + ' awaiting review', mark: '▤', tint: '#F5EDFF', ink: '#7A5FA8' },
        { label: 'Registered educators', value: String(s.customerCount), note: s.subscriberCount + ' on the mailing list', mark: '☺', tint: '#EAF7F1', ink: '#3A836B' },
      ] : [],

      hasChart: !!(s && s.byMonth.length),
      noChart: !!(s && !s.byMonth.length),
      chart: s ? s.byMonth.map(m => {
        const d = new Date(m.month + '-01');
        return {
          label: monthNames[d.getMonth()],
          gross: '$' + Math.round(m.gross),
          grossPct: max ? Math.round(m.gross / max * 100) : 0,
          commPct: max ? Math.round(m.commission / max * 100) : 0,
          grossTip: 'Gross ' + this.money(m.gross) + ' from ' + m.orders + ' orders',
          commTip: 'Commission ' + this.money(m.commission),
        };
      }) : [],

      byPlan: s ? s.byPlan.map(p => ({
        name: p.name,
        count: String(p.vendors),
        pct: planMax ? Math.round(p.vendors / planMax * 100) : 0,
        fill: fills[p.code] || '#3A836B',
      })) : [],

      payoutRows: s ? [
        { label: 'Payouts paid', value: this.money(s.payoutsPaid), ink: '#29483C' },
        { label: 'Payouts pending', value: this.money(s.payoutsPending), ink: '#B9913E' },
        { label: 'Refunded orders', value: String(s.refundedCount), ink: '#C0392B' },
      ] : [],

      hasVendors: !!(s && s.topVendors.length),
      noVendors: !!(s && !s.topVendors.length),
      topVendors: s ? s.topVendors.map(v => ({
        name: v.name,
        href: url('adminVendors', { id: v.vendorId }),
        plan: v.planCode ? this.rules.planByCode(v.planCode).name : '—',
        units: String(v.units),
        gross: this.money(v.gross),
        commission: this.money(v.commission),
      })) : [],

      launchLabel: isPre ? 'Pre-launch — storefront gated' : 'Post-launch — storefront open',
      launchBg: isPre ? '#FFF2DE' : '#EAF7F1',
      launchInk: isPre ? '#B9913E' : '#3A836B',
      launchNote: isPre
        ? 'Visitors see the gated landing page. Storefront routes redirect there for guests.'
        : 'The full storefront is open and the post-launch homepage is live.',
      launchCta: isPre ? 'Open the storefront' : 'Return to pre-launch',
      onToggleLaunch: async () => {
        const next = isPre ? 'post-launch' : 'pre-launch';
        const ok = await this.app.confirmDialog({
          title: isPre ? 'Open the storefront?' : 'Return to pre-launch?',
          body: isPre
            ? 'Every visitor will be able to browse and buy immediately. No redevelopment is needed to switch back.'
            : 'The storefront will be gated again and guests sent to the landing page.',
          confirmLabel: isPre ? 'Go live' : 'Gate the storefront',
          tone: 'primary',
        });
        if (!ok) return;
        await this.platform.setSetting('launchMode', next);
        await this.load();
        this.app.toast(next === 'post-launch' ? 'Storefront is now open.' : 'Storefront gated.', 'success');
      },
    };
  }
}

Admin Orders.j:
const BADGES = {
  completed: { bg: '#EAF7F1', ink: '#3A836B', label: 'Completed' },
  refunded: { bg: '#F5EDFF', ink: '#7A5FA8', label: 'Refunded' },
  cancelled: { bg: '#F3F4F6', ink: '#595959', label: 'Cancelled' },
  failed: { bg: '#FDF1EF', ink: '#C0392B', label: 'Failed' },
  processing: { bg: '#FFF2DE', ink: '#B9913E', label: 'Processing' },
};

class Component extends DCLogic {
  state = { loading: true, rows: [], meta: null, counts: {}, user: null, status: '', query: '', page: 1, open: {} };

  async componentDidMount() {
    const [app, orders, rules, db] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/ordersRepo.js'),
      __ulmImport('assets/js/business-rules.js'),
      __ulmImport('assets/js/db.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, orders, rules, db });
    const user = app.auth.requireRole('admin');
    if (!user) return;
    this.user = user;
    this.setState({ user });
    await this.load();
  }

  async load() {
    const res = await this.orders.listOrders({
      status: this.state.status || undefined,
      q: this.state.query,
      page: this.state.page, pageSize: 15,
    });
    const all = this.db.findAll('orders').rows;
    this.setState({
      loading: false, rows: res.data, meta: res.meta,
      counts: {
        all: all.length,
        completed: all.filter(o => o.status === 'completed').length,
        refunded: all.filter(o => o.status === 'refunded').length,
        failed: all.filter(o => o.status === 'failed' || o.status === 'cancelled').length,
      },
    });
  }

  money(n) { return '$' + Number(n || 0).toFixed(2); }

  settle(item) {
    const v = this.db.findById('vendors', item.vendorId);
    return this.rules.settleLine({ price: item.price, planCode: (v && v.planCode) || item.planCode || 'basic' });
  }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, rows, meta, counts, status, query, page, open } = this.state;
    const pages = meta ? meta.totalPages : 1;

    return {
      subtitle: counts.all ? counts.all + ' orders · ' + counts.completed + ' completed' : '',
      loading, query,
      isEmpty: !loading && rows.length === 0,
      hasRows: !loading && rows.length > 0,
      emptyTitle: query || status ? 'Nothing matches that view' : 'No orders yet',
      emptyBody: query || status
        ? 'Try clearing the search or choosing a different status.'
        : 'Orders appear here as soon as buyers complete a purchase.',

      tabs: [
        { key: '', label: 'All', n: counts.all },
        { key: 'completed', label: 'Completed', n: counts.completed },
        { key: 'refunded', label: 'Refunded', n: counts.refunded },
        { key: 'failed', label: 'Failed', n: counts.failed },
      ].map(t => {
        const on = t.key === status;
        return {
          label: t.label,
          count: String(t.n || 0),
          pressed: on ? 'true' : 'false',
          bg: on ? '#3A836B' : '#FFFFFF',
          border: on ? '#3A836B' : '#E7E9EE',
          ink: on ? '#FFFFFF' : '#29483C',
          pillBg: on ? 'rgba(255,255,255,.22)' : '#F1F3F6',
          pillInk: on ? '#FFFFFF' : '#595959',
          onPick: () => this.setState({ status: t.key, page: 1 }, () => this.load()),
        };
      }),

      rows: rows.map(o => {
        const b = BADGES[o.status] || BADGES.completed;
        const isOpen = !!open[o.id];
        let comm = 0, vend = 0;
        o.items.forEach(i => { const s = this.settle(i); comm += s.commission + s.transactionFee; vend += s.vendorEarnings; });
        return {
          reference: o.reference,
          customer: o.customerName,
          email: o.customerEmail,
          date: new Date(o.placedAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
          vendorLine: o.vendorNames.join(', '),
          statusLabel: b.label, badgeBg: b.bg, badgeInk: b.ink,
          total: this.money(o.total),
          commission: this.money(comm) + ' comm.',
          open: isOpen,
          expanded: isOpen ? 'true' : 'false',
          chevron: isOpen ? 0 : -90,
          rowBg: isOpen ? '#FBFCFD' : '#FFFFFF',
          onToggle: () => this.setState(s => ({ open: Object.assign({}, s.open, { [o.id]: !s.open[o.id] }) })),
          items: o.items.map(i => {
            const s = this.settle(i);
            const v = this.db.findById('vendors', i.vendorId);
            return {
              title: i.title.length > 52 ? i.title.slice(0, 50).trim() + '…' : i.title,
              cover: i.cover,
              href: url('product', { id: i.productId }),
              vendorName: v ? v.storeName : 'Unknown vendor',
              price: this.money(i.price),
              vendorEarnings: this.money(s.vendorEarnings) + ' vendor',
              commission: this.money(s.commission + s.transactionFee) + ' platform',
            };
          }),
          breakdown: [
            { label: 'Subtotal', value: this.money(o.subtotal), ink: '#29483C' },
            { label: 'Discount', value: o.discount ? '−' + this.money(o.discount) : '—', ink: '#595959' },
            { label: 'Vendor earnings', value: this.money(vend), ink: '#3A836B' },
            { label: 'Platform take', value: this.money(comm), ink: '#B9913E' },
            { label: 'Paid by', value: o.paymentMethod, ink: '#29483C' },
          ],
          canRefund: o.status === 'completed',
          onRefund: async () => {
            const ok = await this.app.confirmDialog({
              title: 'Refund ' + o.reference + '?',
              body: this.money(o.total) + ' to ' + o.customerName + '. The order is marked refunded and the vendor earnings reversed.',
              confirmLabel: 'Refund order',
            });
            if (!ok) return;
            await this.orders.refundOrder(o.id, 'Refunded by administrator');
            await this.load();
            this.app.toast('Order refunded.', 'info');
          },
        };
      }),

      showPager: !loading && pages > 1,
      pageLabel: 'Page ' + page + ' of ' + pages,
      prevDisabled: page <= 1, nextDisabled: page >= pages,
      prevOpacity: page <= 1 ? 0.4 : 1, nextOpacity: page >= pages ? 0.4 : 1,
      onPrev: () => { if (page > 1) this.setState({ page: page - 1 }, () => this.load()); },
      onNext: () => { if (page < pages) this.setState({ page: page + 1 }, () => this.load()); },
      onSearch: e => {
        const v = e.target.value;
        clearTimeout(this._t);
        this.setState({ query: v, page: 1 });
        this._t = setTimeout(() => this.load(), 240);
      },
    };
  }
}

