const BADGES = {
  paid: { bg: '#EAF7F1', ink: '#3A836B', label: 'Paid' },
  processing: { bg: '#E3F7FD', ink: '#2F7FA0', label: 'Processing' },
  pending: { bg: '#FFF2DE', ink: '#B9913E', label: 'Pending' },
};

class Component extends DCLogic {
  state = { loading: true, rows: [], all: [], user: null, status: '' };

  async componentDidMount() {
    const [app, finance, rules, db] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/financeRepo.js'),
      __ulmImport('assets/js/business-rules.js'),
      __ulmImport('assets/js/db.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, finance, rules, db });
    const user = app.auth.requireRole('admin');
    if (!user) return;
    this.setState({ user, status: app.router.param('status', '') || '' });
    await this.load();
  }

  async load() {
    const [filtered, all] = await Promise.all([
      this.finance.listPayouts({ status: this.state.status || undefined, pageSize: 200 }),
      this.finance.listPayouts({ pageSize: 500 }),
    ]);
    this.setState({ loading: false, rows: filtered.data, all: all.data });
  }

  money(n) { return '$' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, rows, all, status } = this.state;
    const sum = list => list.reduce((a, p) => a + p.amount, 0);
    const pending = all.filter(p => p.status === 'pending');
    const processing = all.filter(p => p.status === 'processing');
    const paid = all.filter(p => p.status === 'paid');

    return {
      subtitle: pending.length
        ? pending.length + (pending.length === 1 ? ' request' : ' requests') + ' waiting · ' + this.money(sum(pending))
        : 'Nothing waiting to be processed',
      loading,
      isEmpty: !loading && rows.length === 0,
      hasRows: !loading && rows.length > 0,
      emptyTitle: status ? 'No ' + status + ' payouts' : 'No payouts yet',
      emptyBody: status
        ? 'Try a different filter to see the other payouts.'
        : 'When a vendor requests a withdrawal it appears here for processing.',
      cycleNote: this.rules ? this.rules.PAYOUT_CYCLE + '.' : '',

      stats: [
        { label: 'Awaiting payment', value: this.money(sum(pending) + sum(processing)), note: (pending.length + processing.length) + ' requests', ink: '#B9913E' },
        { label: 'Paid to date', value: this.money(sum(paid)), note: paid.length + ' completed payouts', ink: '#3A836B' },
        { label: 'Total requested', value: this.money(sum(all)), note: 'Across all vendors', ink: '#29483C' },
      ],

      tabs: [
        { key: '', label: 'All', n: all.length },
        { key: 'pending', label: 'Pending', n: pending.length },
        { key: 'processing', label: 'Processing', n: processing.length },
        { key: 'paid', label: 'Paid', n: paid.length },
      ].map(t => {
        const on = t.key === status;
        return {
          label: t.label,
          count: String(t.n),
          pressed: on ? 'true' : 'false',
          bg: on ? '#3A836B' : '#FFFFFF',
          border: on ? '#3A836B' : '#E7E9EE',
          ink: on ? '#FFFFFF' : '#29483C',
          pillBg: on ? 'rgba(255,255,255,.22)' : '#F1F3F6',
          pillInk: on ? '#FFFFFF' : '#595959',
          onPick: () => this.setState({ status: t.key }, () => this.load()),
        };
      }),

      rows: rows.map(p => {
        const b = BADGES[p.status] || BADGES.pending;
        return {
          vendorName: p.vendorName,
          vendorHref: url('adminVendors', { id: p.vendorId }),
          planName: p.planCode ? this.rules.planByCode(p.planCode).name : '—',
          period: p.period,
          method: p.method,
          account: p.account || '—',
          statusLabel: b.label, badgeBg: b.bg, badgeInk: b.ink,
          amount: this.money(p.amount),
          dates: p.paidAt
            ? 'Paid ' + new Date(p.paidAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
            : 'Requested ' + new Date(p.requestedAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
          canPay: p.status !== 'paid',
          isPaid: p.status === 'paid',
          onPay: async () => {
            const ok = await this.app.confirmDialog({
              title: 'Mark this payout as paid?',
              body: this.money(p.amount) + ' to ' + p.vendorName + ' via ' + p.method + '. This records the date and notifies the vendor.',
              confirmLabel: 'Mark as paid',
              tone: 'primary',
            });
            if (!ok) return;
            await this.finance.markPaid(p.id);
            await this.load();
            this.app.toast('Payout marked as paid and the vendor notified.', 'success');
          },
        };
      }),
    };
  }
}

