class Component extends DCLogic {
  state = { loading: true, user: null, plans: [], drafts: {}, counts: {} };

  async componentDidMount() {
    const [app, rules, db] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/business-rules.js'),
      __ulmImport('assets/js/db.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, rules, db });
    const user = app.auth.requireRole('admin');
    if (!user) return;

    // Plans are seeded as records so an administrator can edit them (FR-12.2).
    const rows = db.findAll('plans', { sort: [{ field: 'order', dir: 'asc' }] }).rows;
    const vendors = db.findAll('vendors').rows;
    const drafts = {};
    rows.forEach(p => {
      drafts[p.code] = {
        annualFee: p.annualFee === null ? '' : String(p.annualFee),
        payoutRate: p.payoutRate === null ? '' : String(Math.round(p.payoutRate * 100)),
        transactionFee: p.transactionFee === null ? '' : p.transactionFee.toFixed(2),
        transactionFeePct: p.transactionFeePct ? String((p.transactionFeePct * 100).toFixed(1)) : '',
        paidUploadLimit: p.paidUploadLimit === null ? '' : String(p.paidUploadLimit),
      };
    });
    const counts = {};
    rows.forEach(p => { counts[p.code] = vendors.filter(v => v.planCode === p.code).length; });
    this.setState({ loading: false, user, plans: rows, drafts, counts });
  }

  money(n) { return '$' + Number(n || 0).toFixed(2); }

  draftFor(code) { return this.state.drafts[code] || {}; }

  isDirty(p) {
    const d = this.draftFor(p.code);
    const same = (a, b) => String(a) === String(b);
    return !(
      same(d.annualFee, p.annualFee === null ? '' : p.annualFee)
      && same(d.payoutRate, p.payoutRate === null ? '' : Math.round(p.payoutRate * 100))
      && same(d.transactionFee, p.transactionFee === null ? '' : p.transactionFee.toFixed(2))
      && same(d.transactionFeePct, p.transactionFeePct ? (p.transactionFeePct * 100).toFixed(1) : '')
      && same(d.paidUploadLimit, p.paidUploadLimit === null ? '' : p.paidUploadLimit)
    );
  }

  renderVals() {
    const { loading, plans, counts } = this.state;

    const field = (p, key, label, opts) => {
      const d = this.draftFor(p.code);
      return Object.assign({
        id: 'plan-' + p.code + '-' + key,
        label,
        value: d[key] === undefined ? '' : d[key],
        disabled: false,
        bg: '#FFFFFF',
        hasPrefix: false, prefix: '',
        hasSuffix: false, suffix: '',
        placeholder: '',
        help: '',
        onInput: e => {
          const v = e.target.value;
          this.setState(s => ({
            drafts: Object.assign({}, s.drafts, {
              [p.code]: Object.assign({}, s.drafts[p.code], { [key]: v }),
            }),
          }));
        },
      }, opts || {});
    };

    return {
      loading,
      ready: !loading && plans.length > 0,
      subtitle: plans.length ? plans.length + ' plans configured' : '',

      plans: plans.map(p => {
        const d = this.draftFor(p.code);
        const dirty = this.isDirty(p);
        const rate = d.payoutRate === '' ? null : Number(d.payoutRate) / 100;
        const flat = d.transactionFee === '' ? 0 : Number(d.transactionFee);
        const pct = d.transactionFeePct === '' ? 0 : Number(d.transactionFeePct) / 100;
        const gross = 10;
        const share = rate === null ? 0 : gross * rate;
        const fee = gross * pct + flat;
        const vendorGets = Math.max(0, share - fee);

        return {
          name: p.name,
          code: p.code,
          priceLabel: p.annualFee === null ? 'By agreement' : p.annualFee === 0 ? 'FREE' : '$' + p.annualFee + '/yr',
          vendorCount: (counts[p.code] || 0) + (counts[p.code] === 1 ? ' vendor' : ' vendors'),
          badgeText: p.selfService ? 'SELF-SERVICE' : 'BY AGREEMENT',
          badgeBg: p.selfService ? '#EAF7F1' : '#FFF2DE',
          badgeInk: p.selfService ? '#3A836B' : '#B9913E',

          fields: [
            field(p, 'annualFee', 'Annual fee', {
              hasPrefix: true, prefix: '$',
              disabled: !p.selfService,
              bg: p.selfService ? '#FFFFFF' : '#F5F7F9',
              placeholder: p.selfService ? '0' : 'By agreement',
              help: p.selfService ? 'What the vendor pays each year.' : 'Set per contract, not here.',
            }),
            field(p, 'payoutRate', 'Vendor payout share', {
              hasSuffix: true, suffix: '% to vendor',
              placeholder: '—',
              help: rate === null ? 'Free plans pay nothing out.' : 'Platform keeps ' + Math.round((1 - rate) * 100) + '%.',
            }),
            field(p, 'transactionFee', 'Flat transaction fee', {
              hasPrefix: true, prefix: '$',
              placeholder: '0.00',
              help: 'Deducted from the vendor payout on each sale.',
            }),
            field(p, 'transactionFeePct', 'Percentage transaction fee', {
              hasSuffix: true, suffix: '%',
              placeholder: '0',
              help: 'Leave blank for a flat fee only.',
            }),
            field(p, 'paidUploadLimit', 'Paid upload limit', {
              hasSuffix: true, suffix: 'resources',
              placeholder: 'Unlimited',
              help: p.allowsPaidListings ? 'Blank means unlimited.' : 'This plan cannot list paid resources.',
            }),
          ],

          example: [
            { label: 'Buyer pays', value: this.money(gross), weight: 500, ink: '#29483C' },
            { label: 'Vendor share', value: this.money(share), weight: 500, ink: '#595959' },
            { label: 'Transaction fee', value: '−' + this.money(fee), weight: 500, ink: '#595959' },
            { label: 'Vendor receives', value: this.money(vendorGets), weight: 700, ink: '#3A836B' },
            { label: 'Platform keeps', value: this.money(gross - vendorGets), weight: 700, ink: '#B9913E' },
          ],

          dirty,
          clean: !dirty,
          saveBg: dirty ? '#3A836B' : '#C9D4CF',
          saveCursor: dirty ? 'pointer' : 'default',
          saveLabel: dirty ? 'Save changes' : 'No changes',

          onReset: () => {
            this.setState(s => ({
              drafts: Object.assign({}, s.drafts, {
                [p.code]: {
