  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, stats: s } = this.state;
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const max = s && s.byMonth.length ? Math.max.apply(null, s.byMonth.map(m => m.gross)) : 0;
    const vMax = s && s.topVendors.length ? Math.max.apply(null, s.topVendors.map(v => v.gross)) : 0;
    const cMax = s && s.byCategory.length ? Math.max.apply(null, s.byCategory.map(c => c.gross)) : 0;
    const gross = s ? s.grossSales : 0;

    return {
      loading,
      ready: !loading && !!s,
      subtitle: s ? 'Across ' + s.orderCount + ' completed orders and ' + s.vendorCount + ' active vendors' : '',

      stats: s ? [
        { label: 'Gross sales', value: this.money(s.grossSales), note: s.orderCount + ' orders', ink: '#29483C' },
        { label: 'Commission earned', value: this.money(s.commissionEarned), note: gross ? Math.round(s.commissionEarned / gross * 100) + '% of gross' : '', ink: '#B9913E' },
