      ] : [],

      hasChart: !!(s && s.byMonth.length),
      noChart: !!(s && !s.byMonth.length),
      chart: s ? s.byMonth.map(m => {
        const d = new Date(m.month + '-01');
        return {
          label: monthNames[d.getMonth()],
          gross: '$' + Math.round(m.gross),
          orders: m.orders + (m.orders === 1 ? ' order' : ' orders'),
          grossPct: max ? Math.round(m.gross / max * 100) : 0,
          commPct: max ? Math.round(m.commission / max * 100) : 0,
          grossTip: 'Gross ' + this.money(m.gross),
          commTip: 'Commission ' + this.money(m.commission),
        };
      }) : [],

      vendors: s ? s.topVendors.map(v => ({
        name: v.name,
