        units: String(v.units),
        gross: this.money(v.gross),
        commission: this.money(v.commission),
        pct: vMax ? Math.round(v.gross / vMax * 100) : 0,
        pctLabel: gross ? Math.round(v.gross / gross * 100) + '%' : '0%',
      })) : [],

      categories: s ? s.byCategory.map(c => {
        const cat = this.rules.categoryById(c.categoryId);
        return {
          name: cat ? cat.name : 'Uncategorised',
          gross: this.money(c.gross),
          units: c.units + (c.units === 1 ? ' sale' : ' sales'),
          pct: cMax ? Math.round(c.gross / cMax * 100) : 0,
        };
      }) : [],

      health: s ? [
        { label: 'Live resources', value: String(s.productCount), note: s.pendingProducts + ' awaiting review', ink: '#29483C' },
        { label: 'Active vendors', value: String(s.vendorCount), note: s.pendingVendors + ' awaiting approval', ink: '#29483C' },
        { label: 'Registered educators', value: String(s.customerCount), note: 'Buyer accounts', ink: '#29483C' },
        { label: 'Mailing list', value: String(s.subscriberCount), note: 'Pre-launch subscribers', ink: '#29483C' },
        { label: 'Payouts paid', value: this.money(s.payoutsPaid), note: 'To date', ink: '#3A836B' },
        { label: 'Payouts pending', value: this.money(s.payoutsPending), note: 'Awaiting processing', ink: '#B9913E' },
      ] : [],
    };
  }
}

