const BADGES = {
  approved: { bg: '#EAF7F1', ink: '#3A836B', label: 'Active' },
  pending: { bg: '#FFF2DE', ink: '#B9913E', label: 'Awaiting review' },
  declined: { bg: '#F3F4F6', ink: '#595959', label: 'Declined' },
  suspended: { bg: '#FDF1EF', ink: '#C0392B', label: 'Suspended' },
};

class Component extends DCLogic {
  state = { loading: true, rows: [], counts: {}, user: null, status: '', query: '', stats: {} };

  async componentDidMount() {
    const [app, vendors, rules, db] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/vendorsRepo.js'),
      __ulmImport('assets/js/business-rules.js'),
      __ulmImport('assets/js/db.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, vendors, rules, db });
    const user = app.auth.requireRole('admin');
    if (!user) return;
    this.user = user;
    this.setState({ user });
    await this.load();
  }

  async load() {
    const res = await this.vendors.listVendors({
      status: this.state.status || undefined,
      q: this.state.query,
      pageSize: 60,
    });
    const all = this.db.findAll('vendors').rows;
    const stats = {};
    for (const v of res.data) {
      const st = await this.vendors.vendorStats(v.id).catch(() => ({ data: null }));
      stats[v.id] = st.data;
    }
    this.setState({
      loading: false, rows: res.data, stats,
      counts: {
        all: all.length,
        approved: all.filter(v => v.status === 'approved').length,
        pending: all.filter(v => v.status === 'pending').length,
        suspended: all.filter(v => v.status === 'suspended').length,
      },
    });
  }

  money(n) { return '$' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, rows, counts, status, query, stats } = this.state;

    return {
      subtitle: counts.all ? counts.all + ' vendor accounts · ' + counts.approved + ' active' : '',
      queueHref: url('adminVendorQueue'),
      loading, query,
      isEmpty: !loading && rows.length === 0,
      hasRows: !loading && rows.length > 0,
      emptyTitle: query || status ? 'Nothing matches that view' : 'No vendors yet',
      emptyBody: query || status
        ? 'Try clearing the search or choosing a different status.'
        : 'Vendor accounts appear here once someone registers a store.',

      planOptions: (this.rules ? this.rules.PLANS : []).map(p => ({ code: p.code, name: p.name })),

      tabs: [
        { key: '', label: 'All', n: counts.all },
        { key: 'approved', label: 'Active', n: counts.approved },
        { key: 'pending', label: 'Awaiting review', n: counts.pending },
        { key: 'suspended', label: 'Suspended', n: counts.suspended },
      ].map(t => {
        const on = t.key === status;
        return {
          label: t.label,
          count: String(t.n || 0),
          pressed: on ? 'true' : 'false',
          bg: on ? '#3A836B' : '#FFFFFF',
          border: on ? '#3A836B' : '#E7E9EE',
          ink: on ? '#FFFFFF' : '#29483C',
          pillBg: on ? 'rgba(255,255,255,.22)' : '#F1F3F6',
          pillInk: on ? '#FFFFFF' : '#595959',
          onPick: () => this.setState({ status: t.key }, () => this.load()),
        };
      }),

      rows: rows.map(v => {
        const b = BADGES[v.status] || BADGES.pending;
        const st = stats[v.id];
        return {
          storeName: v.storeName,
          storeHref: url('vendorStore', { store: v.slug }),
          catalogueHref: url('adminCatalogue', { vendor: v.id }),
          owner: v.owner,
          email: v.email,
          logo: v.logo,
          hasLogo: !!v.logo,
          noLogo: !v.logo,
          initials: (v.storeName || '?').split(/\s+/).slice(0, 2).map(w => w[0]).join('').toUpperCase(),
          statusLabel: b.label, badgeBg: b.bg, badgeInk: b.ink,
          planCode: v.planCode,
          planLabel: 'Plan for ' + v.storeName,
          meta: [
            v.productCount + (v.productCount === 1 ? ' resource' : ' resources'),
            v.followers + ' followers',
            'joined ' + new Date(v.joinedAt).toLocaleDateString('en-GB', { month: 'short', year: 'numeric' }),
          ].join(' · '),
          gross: st ? this.money(st.grossSales) : '—',
          grossNote: st ? st.unitsSold + ' sold' : '',
          canSuspend: v.status === 'approved',
          canReinstate: v.status === 'suspended',
          isPending: v.status === 'pending',

          onPlan: async e => {
            const code = e.target.value;
            const plan = this.rules.planByCode(code);
            const ok = await this.app.confirmDialog({
              title: 'Move ' + v.storeName + ' to ' + plan.name + '?',
              body: 'Their commission rate, transaction fee and upload limit change immediately. Historic orders keep the rate they were sold at.',
              confirmLabel: 'Change plan',
              tone: 'primary',
            });
            if (!ok) { await this.load(); return; }
            await this.vendors.updateVendor(v.id, { planCode: code });
            const sub = this.db.findAll('subscriptions', { filter: { vendorId: v.id } }).rows[0];
            if (sub) this.db.update('subscriptions', sub.id, { planCode: code, nextBillingAmount: plan.annualFee });
            await this.load();
            this.app.toast(v.storeName + ' moved to ' + plan.name + '.', 'success');
          },
          onSuspend: async () => {
            const ok = await this.app.confirmDialog({
              title: 'Suspend ' + v.storeName + '?',
              body: 'Their store and every listing are hidden from the storefront until reinstated. Existing purchasers keep their downloads.',
              confirmLabel: 'Suspend store',
            });
            if (!ok) return;
            await this.vendors.suspendVendor(v.id, 'Suspended by administrator');
            await this.load();
            this.app.toast('Vendor suspended. Their listings are hidden from the storefront.', 'info');
          },
          onReinstate: async () => {
            await this.vendors.reinstateVendor(v.id);
            await this.load();
            this.app.toast(v.storeName + ' reinstated.', 'success');
          },
        };
      }),

      onSearch: e => {
        const val = e.target.value;
        clearTimeout(this._t);
        this.setState({ query: val });
        this._t = setTimeout(() => this.load(), 240);
      },
    };
  }
}

