class Component extends DCLogic {
  state = {
    loading: true, error: false, products: [], meta: { page: 1, totalPages: 1, total: 0 },
    facets: null, categories: [], grades: [], types: [], themes: [],
    filters: { categories: [], subjects: [], grades: [], types: [], themes: [], priceMin: '', priceMax: '', freeOnly: false, sort: 'relevance', q: '', page: 1 },
    open: { cats: true, price: false, grade: false, type: false, theme: false },
    expanded: {},
  };

  async componentDidMount() {
    try { await this.start(); } catch (e) { window.__ulmErr = String(e && e.stack || e); console.error('Browse init failed', e); this.setState({ loading: false, error: true }); }
  }

  async start() {
    const [app, products, rules, users, cart] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/productsRepo.js'),
      __ulmImport('assets/js/business-rules.js'),
      __ulmImport('assets/js/repositories/usersRepo.js'),
      __ulmImport('assets/js/repositories/cartRepo.js'),
    ]);
    await app.boot();
    this.app = app; this.repo = products; this.rules = rules;
    this.usersRepo = users; this.cartRepo = cart;

    const p = app.router.params();
    const list = v => (v ? String(v).split(',').filter(Boolean) : []);
    const catSlug = p.category || '';
    const cat = catSlug ? rules.categoryBySlug(catSlug) : null;

    const filters = {
      categories: cat ? [cat.id] : list(p.categories),
      subjects: list(p.subjects),
      grades: list(p.grades),
      types: list(p.types),
      themes: list(p.themes),
      priceMin: p.priceMin || '', priceMax: p.priceMax || '',
      freeOnly: p.free === '1',
      sort: p.sort || 'relevance',
      q: p.q || '',
      page: Number(p.page) || 1,
    };

    this.setState({
      filters,
      categories: rules.CATEGORIES,
      grades: rules.GRADES,
      types: rules.RESOURCE_TYPES,
      themes: rules.THEMES,
      expanded: cat ? { [cat.id]: true } : {},
    });

    await this.load();
    const fc = await products.facets();
    this.setState({ facets: fc.data });
  }

  async load(override) {
    this.setState({ loading: true, error: false });
    const f = override || this.state.filters;
    const token = (this._token = (this._token || 0) + 1);
    try {
      const res = await this.repo.listProducts({
        page: f.page, pageSize: 12, q: f.q, sort: f.sort,
        categoryIds: f.categories, subjects: f.subjects, grades: f.grades,
        resourceTypes: f.types, themes: f.themes,
        priceMin: f.priceMin, priceMax: f.priceMax, freeOnly: f.freeOnly,
      });
      if (token !== this._token) return;
      this.setState({ loading: false, products: res.data.map(p => this.decorate(p)), meta: res.meta });
    } catch (err) {
      console.error(err);
      if (token !== this._token) return;
      this.setState({ loading: false, error: true, products: [] });
    }
  }

  set(patch, reload = true) {
    const filters = Object.assign({}, this.state.filters, patch);
    if (!('page' in patch)) filters.page = 1;
    this.setState({ filters });
    this.syncUrl(filters);
    if (reload) this.load(filters);
  }

  syncUrl(f) {
    if (!this.app) return;
    this.app.router.syncQuery({
      q: f.q, categories: f.categories, subjects: f.subjects, grades: f.grades,
      types: f.types, themes: f.themes, priceMin: f.priceMin, priceMax: f.priceMax,
      free: f.freeOnly ? '1' : '', sort: f.sort === 'relevance' ? '' : f.sort,
      page: f.page > 1 ? f.page : '',
    });
  }

  toggleIn(key, value) {
    const cur = this.state.filters[key];
    this.set({ [key]: cur.includes(value) ? cur.filter(v => v !== value) : cur.concat([value]) });
  }

  box(on) {
    return { boxBg: on ? '#3A836B' : '#FFFFFF', boxBorder: on ? '#3A836B' : '#C9D4CF' };
  }

  chip(on) {
    return on
      ? { bg: '#FEDC97', border: '#FEDC97', ink: '#121212', pressed: 'true' }
      : { bg: '#FFFFFF', border: '#DCE7E1', ink: '#595959', pressed: 'false' };
  }

  decorate(p) {
    const url = this.app.router.url;
    const user = this.app.auth.currentUser();
    const saved = user ? this.usersRepo.isWishlisted(user.id, p.id) : false;
    const rounded = Math.round(p.ratingAvg || 0);
    const free = !p.price;
    return {
      id: p.id,
      title: p.title,
      cover: p.cover,
      vendorName: p.vendorName,
      href: url('product', { id: p.id }),
      vendorHref: p.vendorSlug ? url('vendorStore', { store: p.vendorSlug }) : url('browse'),
      stars: [1, 2, 3, 4, 5].map(i => ({ fill: i <= rounded ? '#FFC107' : 'none' })),
      ratingLabel: p.ratingCount ? '(' + Number(p.ratingCount).toLocaleString('en-US') + ')' : '(new)',
      priceLabel: free ? 'Free' : '$' + Number(p.price).toFixed(2),
      hasOriginal: !!p.originalPrice && !free,
      originalLabel: p.originalPrice ? '$' + Number(p.originalPrice).toFixed(2) : '',
      hasBadge: !!p.discountPct || free,
      badgeText: p.discountPct ? p.discountPct + '% off' : 'Free',
      badgeBg: p.discountPct ? '#FEDC97' : '#3A836B',
      badgeInk: p.discountPct ? '#121212' : '#FFFFFF',
      heartColor: saved ? '#C0392B' : '#29483C',
      heartFill: saved ? '#C0392B' : 'none',
      wishPressed: saved ? 'true' : 'false',
      wishLabel: (saved ? 'Remove from wishlist: ' : 'Save to wishlist: ') + p.title,
      addText: free ? 'Get' : 'Add',
      addLabel: (free ? 'Get ' : 'Add to cart: ') + p.title,
      onWishlist: async () => {
        const u = this.app.auth.currentUser();
        if (!u) { this.app.toast('Sign in to save resources to your wishlist.', 'info'); return; }
        const res = await this.usersRepo.toggleWishlist(u.id, p.id);
        this.app.toast(res.data.saved ? 'Saved to your wishlist.' : 'Removed from your wishlist.', 'success');
        this.setState(s => ({
          products: s.products.map(row => row.id !== p.id ? row : Object.assign({}, row, {
            heartColor: res.data.saved ? '#C0392B' : '#29483C',
            heartFill: res.data.saved ? '#C0392B' : 'none',
            wishPressed: res.data.saved ? 'true' : 'false',
          })),
        }));
      },
      onAdd: async () => {
        try {
          const u = this.app.auth.currentUser();
          await this.cartRepo.addToCart(this.cartRepo.cartOwner(u), p.id, { isCustomer: !!u });
          this.app.toast('Added to cart.', 'success');
        } catch (err) {
          this.app.toast(this.app.readError(err).message, 'error');
        }
      },
    };
  }

  renderVals() {
    const { loading, error, products, meta, filters, open, expanded, categories, grades, types, themes, facets } = this.state;
    const url = this.app ? this.app.router.url : (() => '#');
    const catById = id => categories.find(c => c.id === id);
    const activeCat = filters.categories.length === 1 ? catById(filters.categories[0]) : null;

    const chips = [];
    filters.categories.forEach(id => {
      const c = catById(id);
      if (c) chips.push({ label: c.name, bg: '#FEDC97', border: '#FEDC97', icon: 'M5 5l14 14M19 5 5 19', onRemove: () => this.toggleIn('categories', id) });
    });
    filters.subjects.forEach(s => chips.push({ label: s, bg: '#FEDC97', border: '#FEDC97', icon: 'M5 5l14 14M19 5 5 19', onRemove: () => this.toggleIn('subjects', s) }));
    filters.grades.forEach(g => chips.push({ label: g, bg: '#FEDC97', border: '#FEDC97', icon: 'M5 5l14 14M19 5 5 19', onRemove: () => this.toggleIn('grades', g) }));
    filters.types.forEach(t => chips.push({ label: t, bg: '#FFFFFF', border: '#DCE7E1', icon: 'M5 5l14 14M19 5 5 19', onRemove: () => this.toggleIn('types', t) }));
    filters.themes.forEach(t => chips.push({ label: t, bg: '#FFFFFF', border: '#DCE7E1', icon: 'M5 5l14 14M19 5 5 19', onRemove: () => this.toggleIn('themes', t) }));
    if (filters.freeOnly) chips.push({ label: 'Free only', bg: '#FFFFFF', border: '#DCE7E1', icon: 'M5 5l14 14M19 5 5 19', onRemove: () => this.set({ freeOnly: false }) });
    if (filters.q) chips.push({ label: '“' + filters.q + '”', bg: '#FFFFFF', border: '#DCE7E1', icon: 'M5 5l14 14M19 5 5 19', onRemove: () => this.set({ q: '' }) });

    const total = meta.total;
    const totalPages = meta.totalPages || 1;
    const pageNums = [];
    if (totalPages <= 7) { for (let i = 1; i <= totalPages; i++) pageNums.push(i); }
    else {
      pageNums.push(1, 2, 3, 4);
      if (filters.page > 5 && filters.page < totalPages - 1) pageNums.push('…', filters.page);
      pageNums.push('…', totalPages);
    }

    const crumbs = [
      { label: 'All resources', href: url('browse'), color: '#595959', weight: 400, current: undefined },
    ];
    if (activeCat) crumbs.push({ label: activeCat.name, href: url('browse', { category: activeCat.slug }), color: '#29483C', weight: 600, current: 'page' });
    else if (filters.q) crumbs.push({ label: 'Search: ' + filters.q, href: '#', color: '#29483C', weight: 600, current: 'page' });

    return {
      activeCategory: activeCat ? activeCat.slug : '',
      query: filters.q,
