      pageTitle: activeCat ? activeCat.name + ' Resources' : filters.q ? 'Results for “' + filters.q + '”' : 'All Resources',
      resultsLine: loading ? 'Loading resources…'
        : 'Showing ' + total.toLocaleString('en-US') + ' educational worksheet' + (total === 1 ? '' : 's') + ', game' + (total === 1 ? '' : 's') + ', and activit' + (total === 1 ? 'y' : 'ies'),
      loading,
      hasError: !loading && error,
      isEmpty: !loading && !error && products.length === 0,
      hasResults: !loading && !error && products.length > 0,
      products,
      skeletons: [1, 2, 3, 4, 5, 6],
      appliedChips: chips,
      sort: filters.sort,
      onSort: e => this.set({ sort: e.target.value }),
      onRetry: () => this.load(),

      catsOpen: open.cats, catsChevron: open.cats ? 0 : -90,
      priceOpen: open.price, priceChevron: open.price ? 0 : -90,
      gradeOpen: open.grade, gradeChevron: open.grade ? 0 : -90,
      typeOpen: open.type, typeChevron: open.type ? 0 : -90,
      themeOpen: open.theme, themeChevron: open.theme ? 0 : -90,
      toggleCategories: () => this.setState(s => ({ open: Object.assign({}, s.open, { cats: !s.open.cats }) })),
      togglePrice: () => this.setState(s => ({ open: Object.assign({}, s.open, { price: !s.open.price }) })),
      toggleGrade: () => this.setState(s => ({ open: Object.assign({}, s.open, { grade: !s.open.grade }) })),
      toggleType: () => this.setState(s => ({ open: Object.assign({}, s.open, { type: !s.open.type }) })),
      toggleTheme: () => this.setState(s => ({ open: Object.assign({}, s.open, { theme: !s.open.theme }) })),

      categoryRows: categories.map(c => {
        const on = filters.categories.includes(c.id);
        const isOpen = !!expanded[c.id];
        return Object.assign({
          name: c.name,
          checked: on,
          expanded: isOpen,
          chevron: isOpen ? 90 : 0,
          expandLabel: (isOpen ? 'Collapse ' : 'Expand ') + c.name,
          onToggle: () => this.toggleIn('categories', c.id),
          onExpand: () => this.setState(s => ({ expanded: Object.assign({}, s.expanded, { [c.id]: !s.expanded[c.id] }) })),
          subjects: c.subjects.map(s => Object.assign({
            name: s, checked: filters.subjects.includes(s),
            onToggle: () => this.toggleIn('subjects', s),
          }, this.box(filters.subjects.includes(s)))),
        }, this.box(on));
      }),

      gradeChips: grades.map(g => Object.assign({ name: g, onToggle: () => this.toggleIn('grades', g) }, this.chip(filters.grades.includes(g)))),
      themeChips: themes.map(t => Object.assign({ name: t, onToggle: () => this.toggleIn('themes', t) }, this.chip(filters.themes.includes(t)))),
      typeRows: types.map(t => Object.assign({
        name: t, checked: filters.types.includes(t),
        count: facets && facets.resourceTypes[t] ? facets.resourceTypes[t] : 0,
        onToggle: () => this.toggleIn('types', t),
      }, this.box(filters.types.includes(t)))),

      freeChecked: filters.freeOnly,
      freeBg: filters.freeOnly ? '#3A836B' : '#FFFFFF',
      freeBorder: filters.freeOnly ? '#3A836B' : '#C9D4CF',
      onToggleFree: () => this.set({ freeOnly: !filters.freeOnly }),
      priceMin: filters.priceMin,
      priceMax: filters.priceMax,
      onPriceMin: e => this.set({ priceMin: e.target.value }),
      onPriceMax: e => this.set({ priceMax: e.target.value }),
      onClearAll: () => this.set({ categories: [], subjects: [], grades: [], types: [], themes: [], priceMin: '', priceMax: '', freeOnly: false, q: '' }),
      onApply: () => { this.load(); this.app.toast('Filters applied.', 'success'); },

      showPagination: !loading && !error && totalPages > 1,
      pageButtons: pageNums.map((n, i) => {
        if (n === '…') return { text: '…', label: 'More pages', disabled: true, cursor: 'default', bg: '#FFFFFF', border: 'transparent', ink: '#2B2B2B', weight: 500, current: undefined, onClick: () => {} };
        const active = n === filters.page;
        return {
          text: String(n), label: 'Page ' + n, disabled: false, cursor: 'pointer',
          bg: active ? '#3A836B' : '#FFFFFF', border: active ? '#3A836B' : '#EDF0EE',
          ink: active ? '#FFFFFF' : '#2B2B2B', weight: active ? 700 : 500,
          current: active ? 'page' : undefined,
          onClick: () => { this.set({ page: n }); window.scrollTo({ top: 220, behavior: 'smooth' }); },
        };
      }),
      prevDisabled: filters.page <= 1,
      nextDisabled: filters.page >= totalPages,
      prevOpacity: filters.page <= 1 ? 0.4 : 1,
      nextOpacity: filters.page >= totalPages ? 0.4 : 1,
      onPrev: () => { if (filters.page > 1) { this.set({ page: filters.page - 1 }); window.scrollTo({ top: 220, behavior: 'smooth' }); } },
      onNext: () => { if (filters.page < totalPages) { this.set({ page: filters.page + 1 }); window.scrollTo({ top: 220, behavior: 'smooth' }); } },
    };
  }
}

