class Component extends DCLogic {
  state = { loading: true, cart: null, user: null };

  async componentDidMount() {
    const [app, cart] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/cartRepo.js'),
    ]);
    await app.boot();
    this.app = app; this.cartRepo = cart;
    const user = app.auth.currentUser();
    this.owner = cart.cartOwner(user);
    // A guest cart follows the buyer into their account on sign-in.
    if (user) cart.mergeGuestCart(user.id);
    const res = await cart.getCart(this.owner);
    this.setState({ loading: false, cart: res.data, user });
  }

  money(n) { return n === 0 ? 'Free' : '$' + Number(n).toFixed(2); }

  async refresh() {
    const res = await this.cartRepo.getCart(this.owner);
    this.setState({ cart: res.data });
  }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, cart, user } = this.state;
    const items = cart ? cart.items : [];
    const blocked = items.some(i => !i.available);

    const byVendor = {};
    items.forEach(i => {
      byVendor[i.vendorId] = byVendor[i.vendorId] || { vendorId: i.vendorId, vendorName: i.vendorName, items: [] };
      byVendor[i.vendorId].items.push(i);
    });

    return {
      browseHref: url('browse'),
      loginHref: url('login', { next: 'Cart.dc.html' }),
      loading,
      isEmpty: !loading && items.length === 0,
      hasItems: !loading && items.length > 0,
      isGuest: !loading && !user && items.length > 0,
      summaryLine: loading ? 'Loading…'
        : items.length === 0 ? ''
        : items.length + (items.length === 1 ? ' resource' : ' resources')
          + ' from ' + cart.vendorCount + (cart.vendorCount === 1 ? ' vendor' : ' vendors'),

      groups: Object.values(byVendor).map(g => ({
        vendorName: g.vendorName,
        vendorHref: url('browse', { q: g.vendorName }),
        countLabel: g.items.length + (g.items.length === 1 ? ' item' : ' items'),
        items: g.items.map(i => ({
          title: i.title,
          href: url('product', { id: i.productId }),
          cover: i.cover,
          meta: [i.fileType, i.pageCount ? i.pageCount + ' pages' : null].filter(Boolean).join(' · '),
          price: this.money(i.price),
          unavailable: !i.available,
          removeLabel: 'Remove ' + i.title + ' from your cart',
          onRemove: async () => {
            await this.cartRepo.removeFromCart(this.owner, i.id);
            await this.refresh();
            this.app.toast('Removed from cart.', 'success');
          },
        })),
      })),

      totals: [
        { label: 'Subtotal', value: '$' + (cart ? cart.subtotal : 0).toFixed(2) },
        { label: 'Digital delivery', value: 'Included' },
      ],
      total: '$' + (cart ? cart.total : 0).toFixed(2),
      checkoutBlocked: blocked,
      checkoutCursor: blocked ? 'not-allowed' : 'pointer',
      checkoutOpacity: blocked ? 0.6 : 1,
      checkoutLabel: blocked ? 'Remove unavailable items' : 'Proceed to checkout',

      onCheckout: () => {
        if (blocked) return;
        if (!(this.user || this.state.user)) { this.app.router.go('login', { next: 'Checkout.dc.html', reason: 'session' }); return; }
        this.app.router.go('checkout');
      },
      onClear: async () => {
        const ok = await this.app.confirmDialog({
          title: 'Empty your cart?',
          body: 'Every resource in the cart will be removed. Nothing you have already purchased is affected.',
          confirmLabel: 'Empty cart',
        });
        if (!ok) return;
        await this.cartRepo.clearCart(this.owner);
        await this.refresh();
        this.app.toast('Cart emptied.', 'info');
      },
    };
  }
}

