      __ulmImport('assets/js/repositories/cartRepo.js'),
      __ulmImport('assets/js/repositories/ordersRepo.js'),
      __ulmImport('assets/js/validation.js'),
      __ulmImport('assets/js/db.js'),
    ]);
    await app.boot();
    this.app = app; this.cartRepo = cart; this.orders = orders; this.validation = validation; this.db = db;
    const user = app.auth.requireRole('customer', 'vendor', 'admin');
    if (!user) return;
    this.owner = user.id;
    cart.mergeGuestCart(user.id);
    const res = await cart.getCart(user.id);
    this.setState(s => ({
      loading: false, cart: res.data, user,
      values: Object.assign({}, s.values, { email: user.email, cardName: user.name }),
    }));
  }

  field(name) {
    const err = this.state.errors[name];
    const cap = name.charAt(0).toUpperCase() + name.slice(1);
    return {
      ['v' + cap]: this.state.values[name],
      [name + 'Error']: err || '',
      [name + 'Border']: err ? '#C0392B' : '#CAC4D0',
      [name + 'LabelColor']: err ? '#C0392B' : '#49454F',
      [name + 'Invalid']: err ? 'true' : 'false',
    };
  }

  discount() {
    const c = this.state.coupon;
    const sub = this.state.cart ? this.state.cart.subtotal : 0;
    if (!c || !this.state.couponOk) return 0;
    const d = c.type === 'percent' ? sub * c.value / 100 : Math.min(sub, c.value);
    return Math.round(d * 100) / 100;
  }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, cart, busy, errors, formError, values, couponMessage, couponOk } = this.state;
    const items = cart ? cart.items : [];
    const sub = cart ? cart.subtotal : 0;
    const disc = this.discount();
    const total = Math.max(0, Math.round((sub - disc) * 100) / 100);
    const isCard = values.paymentMethod === 'card';

    const totals = [{ label: 'Subtotal', value: '$' + sub.toFixed(2), color: '#595959' }];
    if (disc > 0) totals.push({ label: 'Coupon ' + values.couponCode.toUpperCase(), value: '−$' + disc.toFixed(2), color: '#3A836B' });
    totals.push({ label: 'Digital delivery', value: 'Included', color: '#595959' });

