      acceptTermsError: errors.acceptTerms || '',
      acceptTermsInvalid: errors.acceptTerms ? 'true' : 'false',
      vAcceptTerms: this.state.values.acceptTerms,
      onInput: e => {
        const { name, value } = e.target;
        this.setState(s => ({
          values: Object.assign({}, s.values, { [name]: value }),
          errors: Object.assign({}, s.errors, { [name]: null }),
          formError: '',
        }));
      },
      onCheck: e => {
        const { name, checked } = e.target;
        this.setState(s => ({
          values: Object.assign({}, s.values, { [name]: checked }),
          errors: Object.assign({}, s.errors, { [name]: null }),
        }));
      },
      onSubmit: async e => {
        e.preventDefault();
        if (this.state.busy) return;
        const { valid, errors: errs } = this.validation.validate(this.state.values, this.validation.schemas.registerCustomer);
        if (!valid) {
          this.setState({ errors: errs });
          const first = Object.keys(errs)[0];
          const el = document.getElementById('rc-' + first);
          if (el) el.focus();
          return;
        }
        this.setState({ busy: true, errors: {}, formError: '' });
        try {
