          values: Object.assign({}, s.values, { [name]: value }),
          errors: Object.assign({}, s.errors, { [name]: null }),
          formError: '',
        }));
      },
      onSubmit: async e => {
        e.preventDefault();
        if (this.state.busy) return;
        const r = this.validation.rules;
        const { valid, errors: errs } = this.validation.validate(this.state.values, {
          token: [r.required()],
          password: [r.required(), r.password()],
