class Component extends DCLogic {
  state = { ready: false, user: null, cartCount: 0, menuOpen: false, cats: [] };

  async componentDidMount() {
    const [app, rules, cart, platform] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/business-rules.js'),
      __ulmImport('assets/js/repositories/cartRepo.js'),
      __ulmImport('assets/js/repositories/platformRepo.js'),
    ]);
    await app.boot();
    this.app = app; this.cartRepo = cart; this.platform = platform;
    this.sync(rules.CATEGORIES);
    this.offSession = app.auth.onSessionChange(() => this.sync(rules.CATEGORIES));
    this.offDb = app.db.onChange(() => this.sync(rules.CATEGORIES));
    this.onDocClick = e => {
      if (this.state.menuOpen && !e.target.closest('[data-testid="account-menu"],[data-testid="account-menu-trigger"]')) {
        this.setState({ menuOpen: false });
      }
    };
    this.onEsc = e => { if (e.key === 'Escape' && this.state.menuOpen) this.setState({ menuOpen: false }); };
    document.addEventListener('click', this.onDocClick);
    document.addEventListener('keydown', this.onEsc);
  }

  componentWillUnmount() {
    if (this.offSession) this.offSession();
    if (this.offDb) this.offDb();
    document.removeEventListener('click', this.onDocClick);
    document.removeEventListener('keydown', this.onEsc);
  }

  sync(cats) {
    const user = this.app.auth.currentUser();
    const owner = this.cartRepo.cartOwner(user);
    this.setState({ ready: true, user, cats, cartCount: this.cartRepo.cartCount(owner) });
  }

  menuFor(user) {
    // State can survive a remount that clears instance fields, so never assume
    // this.app is present just because a user is.
    if (!user || !this.app) return [];
    const { url } = this.app.router;
    if (user.role === 'admin') {
      const q = this.platform ? this.platform.queueCountsSync() : { vendors: 0, products: 0, payouts: 0 };
      return [
        { label: 'Admin dashboard', href: url('adminDashboard'), badge: 0 },
        { label: 'Vendor queue', href: url('adminVendorQueue'), badge: q.vendors },
        { label: 'Product queue', href: url('adminProductQueue'), badge: q.products },
        { label: 'Payouts', href: url('adminPayouts'), badge: q.payouts },
        { label: 'Reports', href: url('adminReports'), badge: 0 },
      ];
    }
    if (user.role === 'vendor') {
      const pending = user.vendor && user.vendor.status !== 'approved';
      return [
        { label: pending ? 'Approval status' : 'Vendor dashboard', href: url(pending ? 'vendorPending' : 'vendorDashboard'), badge: 0 },
        { label: 'My products', href: url('vendorProducts'), badge: 0 },
        { label: 'Orders', href: url('vendorOrders'), badge: 0 },
        { label: 'Payments', href: url('vendorPayments'), badge: 0 },
        { label: 'Subscription', href: url('vendorSubscription'), badge: 0 },
        { label: 'My downloads', href: url('accountDownloads'), badge: 0 },
      ];
    }
    return [
      { label: 'My orders', href: url('accountOrders'), badge: 0 },
      { label: 'Downloads', href: url('accountDownloads'), badge: 0 },
      { label: 'Wishlist', href: url('accountWishlist'), badge: 0 },
      { label: 'Following', href: url('accountFollowing'), badge: 0 },
      { label: 'Profile', href: url('accountProfile'), badge: 0 },
    ];
  }

  renderVals() {
    const p = this.props || {};
    const { user, cats, cartCount, menuOpen, ready } = this.state;
    const url = this.app ? this.app.router.url : (r => r);
    const active = p.active || '';

    const navItems = (cats.length ? cats : []).map(c => ({
      name: c.name,
      href: url('browse', { category: c.slug }),
      current: active === c.slug ? 'page' : undefined,
      weight: active === c.slug ? 600 : 500,
      underline: active === c.slug ? '#FEDC97' : 'transparent',
    })).concat(cats.length ? [{
      name: 'About Us', href: url('about'),
      current: active === 'about' ? 'page' : undefined,
      weight: active === 'about' ? 600 : 500,
      underline: active === 'about' ? '#FEDC97' : 'transparent',
    }] : []);

    return {
      ready,
      navItems,
      isGuest: ready && !user,
      isSignedIn: !!user,
      userName: user ? user.name : '',
      userFirstName: user ? user.firstName : '',
      userInitials: user ? (user.firstName[0] + (user.lastName ? user.lastName[0] : '')).toUpperCase() : '',
      roleLabel: user ? ({ admin: 'Administrator', vendor: user.vendor ? user.vendor.storeName : 'Vendor', customer: user.roleLabel || 'Educator' })[user.role] : '',
      menuItems: this.menuFor(user),
      menuOpen,
      cartCount,
      hasCartItems: cartCount > 0,
      cartLabel: cartCount ? `Cart, ${cartCount} item${cartCount === 1 ? '' : 's'}` : 'Cart, empty',
      searchQuery: p.searchQuery || '',
      homeHref: url(p.launchMode === 'post-launch' ? 'home' : 'landing'),
      loginHref: url('login'),
      registerHref: url('registerCustomer'),
      vendorLoginHref: url('registerVendor'),
      cartHref: url('cart'),
      toggleMenu: e => { e.stopPropagation(); this.setState(s => ({ menuOpen: !s.menuOpen })); },
      onSignOut: async () => { await this.app.auth.logout(); this.app.router.go('landing'); },
      onSearch: e => {
        e.preventDefault();
        const q = new FormData(e.target).get('q');
        this.app.router.go('browse', q ? { q } : {});
      },
    };
  }
}

