const STEPS = [
  { label: 'Store identity', title: 'Tell buyers about your store', blurb: 'This is what appears on your public store page and beside every resource you publish.' },
  { label: 'Branding', title: 'Add your logo and banner', blurb: 'Optional, but a finished storefront earns more trust. You can change these any time.' },
  { label: 'Payouts', title: 'Where should your earnings go?', blurb: 'We use this to pay you. It is never shown to buyers.' },
  { label: 'Content standard', title: 'Confirm the content standard', blurb: 'Every vendor agrees to the same standard before publishing.' },
];

class Component extends DCLogic {
  state = {
    step: 1, busy: false, errors: {}, formError: '', user: null, vendor: null, plan: null,
    values: { storeName: '', slug: '', bio: '', logo: null, banner: null, payoutMethod: 'PayPal', payoutAccount: '', confirmStandard: false },
  };

  async componentDidMount() {
    const [app, vendors, rules, validation, db] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/vendorsRepo.js'),
      __ulmImport('assets/js/business-rules.js'),
      __ulmImport('assets/js/validation.js'),
      __ulmImport('assets/js/db.js'),
    ]);
    await app.boot();
    this.app = app; this.vendors = vendors; this.validation = validation; this.rules = rules; this.db = db;
    const user = app.auth.requireRole('vendor', 'admin');
    if (!user) return;
    const v = user.vendor;
    if (v && v.status !== 'approved') { app.router.replace('vendorPending'); return; }
    this.setState({
      user, vendor: v || null,
      plan: v ? rules.planByCode(v.planCode) : null,
      values: Object.assign({}, this.state.values, v ? {
        storeName: v.storeName || '', slug: v.slug || '', bio: v.bio || '',
        logo: v.logo || null, banner: v.banner || null,
        payoutMethod: v.payoutMethod || 'PayPal', payoutAccount: v.payoutAccount || '',
      } : {}),
    });
  }

  field(name) {
    const err = this.state.errors[name];
    const cap = name.charAt(0).toUpperCase() + name.slice(1);
    return {
      ['v' + cap]: this.state.values[name],
      [name + 'Error']: err || '',
      [name + 'Border']: err ? '#C0392B' : '#CAC4D0',
      [name + 'LabelColor']: err ? '#C0392B' : '#49454F',
      [name + 'Invalid']: err ? 'true' : 'false',
    };
  }

  schemaFor(step) {
    const r = this.validation.rules;
    if (step === 1) return { storeName: [r.required(), r.minLength(3), r.maxLength(60)], slug: [r.required(), r.slug()], bio: [r.required(), r.minLength(40), r.maxLength(600)] };
    if (step === 3) return { payoutMethod: [r.required()], payoutAccount: [r.required()] };
    if (step === 4) return { confirmStandard: [r.accepted()] };
    return {};
  }

  async readImage(file) {
    if (!file) return null;
    return this.db.fileToDataUrl(file);
  }

  renderVals() {
    const { step, busy, errors, formError, values, vendor, plan } = this.state;
    const url = this.app ? this.app.router.url : (() => '#');
    const meta = STEPS[step - 1];
    const bioLen = (values.bio || '').length;

    return Object.assign({
      homeHref: url('landing'),
      stepNumber: String(step),
      percent: Math.round(step / 4 * 100),
      stepTitle: meta.title,
      stepBlurb: meta.blurb,
      isStep1: step === 1, isStep2: step === 2, isStep3: step === 3, isStep4: step === 4,
      hasError: !!formError,
      formError,
      busy,
      submitOpacity: busy ? 0.72 : 1,
      nextLabel: busy ? 'Saving…' : step === 4 ? 'Finish and open my dashboard' : 'Save and continue',
      canGoBack: step > 1,
      canSkip: step === 2,

      stepTabs: STEPS.map((s, i) => {
        const n = i + 1;
        const done = n < step;
        const cur = n === step;
        return {
          label: s.label,
          mark: done ? '✓' : String(n),
          bg: cur ? '#F2FAF7' : 'transparent',
          dotBg: done ? '#3A836B' : cur ? '#3A836B' : '#EDF0EE',
          dotInk: done || cur ? '#FFFFFF' : '#9AA5A0',
          ink: done || cur ? '#29483C' : '#9AA5A0',
          weight: cur ? 600 : 500,
        };
      }),

      bioHelp: errors.bio || bioLen + ' / 600 characters — at least 40.',
      bioHelpColor: errors.bio ? '#C0392B' : '#49454F',

      hasLogo: !!values.logo, noLogo: !values.logo,
      hasBanner: !!values.banner, noBanner: !values.banner,

      payoutOptions: (this.rules ? this.rules.PAYOUT_METHODS : ['PayPal', 'Bank deposit']).map(value => {
        const on = values.payoutMethod === value;
        return {
          value, checked: on,
          bg: on ? '#F2FAF7' : '#FFFFFF',
          border: on ? '#3A836B' : '#EDF0EE',
          dotBg: on ? '#3A836B' : '#FFFFFF',
          dotBorder: on ? '#3A836B' : '#CAC4D0',
          dotInner: on ? 'inset 0 0 0 3px #FFFFFF' : 'none',
          onPick: () => this.setState(s => ({ values: Object.assign({}, s.values, { payoutMethod: value }), errors: Object.assign({}, s.errors, { payoutMethod: null }) })),
        };
      }),
      payoutAccountLabel: values.payoutMethod === 'PayPal' ? 'PayPal email' : 'Bank account details',
      payoutAccountPlaceholder: values.payoutMethod === 'PayPal' ? 'you@yourstore.com' : 'Bank name and account number',

      planTerms: plan ? [
        { label: 'Plan', value: plan.name },
        { label: 'Your payout share', value: plan.payoutRate === null ? '—' : Math.round(plan.payoutRate * 100) + '%' },
        { label: 'Per transaction', value: plan.transactionFee === null ? '—' : (plan.transactionFeePct ? (plan.transactionFeePct * 100).toFixed(1) + '% + ' : '') + '$' + plan.transactionFee.toFixed(2) },
      ] : [],

      standard: (this.rules ? this.rules.CONTENT_STANDARD : []).map(text => ({ text })),

      review: [
        { label: 'Store name', value: values.storeName || '—' },
        { label: 'Store address', value: values.slug ? '/store/' + values.slug : '—' },
        { label: 'Biography', value: bioLen ? bioLen + ' characters' : 'Not written yet' },
        { label: 'Logo', value: values.logo ? 'Uploaded' : 'Not set' },
        { label: 'Banner', value: values.banner ? 'Uploaded' : 'Not set' },
        { label: 'Payouts', value: values.payoutMethod + (values.payoutAccount ? ' · ' + values.payoutAccount : '') },
      ],

      confirmStandardBg: values.confirmStandard ? '#3A836B' : '#FFFFFF',
      confirmStandardBorder: errors.confirmStandard ? '#C0392B' : values.confirmStandard ? '#3A836B' : '#CAC4D0',
      confirmStandardError: errors.confirmStandard || '',
      vConfirmStandard: values.confirmStandard,

      onInput: e => {
        const { name, value } = e.target;
        this.setState(s => {
          const next = Object.assign({}, s.values, { [name]: value });
          // Keep the address in step with the name until the user edits it directly.
          if (name === 'storeName' && !s.touchedSlug) {
            next.slug = String(value || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
          }
          return {
            values: next,
            touchedSlug: name === 'slug' ? true : s.touchedSlug,
            errors: Object.assign({}, s.errors, { [name]: null }),
            formError: '',
          };
        });
      },
      onCheck: e => {
        const { name, checked } = e.target;
        this.setState(s => ({
          values: Object.assign({}, s.values, { [name]: checked }),
          errors: Object.assign({}, s.errors, { [name]: null }),
        }));
      },
      onLogo: async e => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const logo = await this.readImage(file);
        this.setState(s => ({ values: Object.assign({}, s.values, { logo }) }));
      },
      onBanner: async e => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const banner = await this.readImage(file);
        this.setState(s => ({ values: Object.assign({}, s.values, { banner }) }));
      },
      onBack: () => this.setState(s => ({ step: Math.max(1, s.step - 1), formError: '' })),
      onSkip: () => this.setState({ step: 3, formError: '' }),

      onNext: async e => {
        e.preventDefault();
        if (this.state.busy) return;
        const schema = this.schemaFor(this.state.step);
        const { valid, errors: errs } = this.validation.validate(this.state.values, schema);
        if (!valid) {
          this.setState({ errors: errs });
          const el = document.getElementById('sw-' + Object.keys(errs)[0]);
          if (el) el.focus();
          return;
        }
        if (this.state.step < 4) {
          this.setState(s => ({ step: s.step + 1, errors: {}, formError: '' }));
          window.scrollTo({ top: 0, behavior: 'smooth' });
          return;
        }
        this.setState({ busy: true, formError: '' });
        try {
          const v = this.state.values;
          await this.vendors.updateVendor(this.state.vendor.id, {
            storeName: v.storeName, slug: v.slug, bio: v.bio,
            logo: v.logo, banner: v.banner,
            payoutMethod: v.payoutMethod, payoutAccount: v.payoutAccount,
            setupComplete: true,
          });
          this.app.toast('Store setup complete. Publish your first resource.', 'success');
          this.app.router.go('vendorDashboard');
        } catch (err) {
          const { message, fields } = this.app.readError(err);
          this.setState({ busy: false, formError: message, errors: fields || {} });
        }
      },
    }, this.field('storeName'), this.field('slug'), this.field('bio'),
       this.field('payoutMethod'), this.field('payoutAccount'));
  }
}

