            at: new Date(r.at).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
          })),
          replyOpen: isReplying,
          replyClosed: !isReplying,
          replyCta: replies.length ? 'Reply again' : 'Write a reply',
          inputId: 'reply-' + m.id,
          onReply: () => this.setState({ replyTo: m.id }),
          onCancel: () => this.setState({ replyTo: null }),
          onSend: async e => {
            e.preventDefault();
            const body = new FormData(e.target).get('body');
            if (!String(body || '').trim()) return;
            await this.platform.replyToMessage(m.id, body);
            this.setState({ replyTo: null });
            await this.load();
