    const [app, orders, rules] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/ordersRepo.js'),
      __ulmImport('assets/js/business-rules.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, orders, rules });
    const user = app.auth.requireRole('vendor', 'admin');
    if (!user) return;
    this.vid = user.vendorId || (user.vendor && user.vendor.id) || 'v-1';
    const openId = app.router.param('id');
    this.setState({
      user,
      plan: rules.planByCode(user.vendor ? user.vendor.planCode : 'basic'),
      open: openId ? { [openId]: true } : {},
    });
    await this.load();
  }

  async load() {
    this.setState({ loading: true });
    const res = await this.orders.listOrders({
      vendorId: this.vid,
      status: this.state.status || undefined,
      q: this.state.query,
      page: this.state.page, pageSize: 12,
    });
    this.setState({ loading: false, rows: res.data, meta: res.meta });
  }

  money(n) { return '$' + Number(n || 0).toFixed(2); }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, rows, meta, status, query, page, open, plan } = this.state;
    const pages = meta ? meta.totalPages : 1;
    const total = meta ? meta.total : 0;

    return {
      subtitle: total ? total + (total === 1 ? ' order' : ' orders') + ' containing your resources' : '',
      loading, status, query,
      isEmpty: !loading && rows.length === 0,
      hasRows: !loading && rows.length > 0,
      emptyTitle: query || status ? 'Nothing matches that view' : 'No orders yet',
      emptyBody: query || status
        ? 'Try clearing the search or choosing a different status.'
        : 'When a buyer purchases one of your resources the order appears here with your earnings.',

      rows: rows.map(o => {
        const b = BADGES[o.status] || BADGES.completed;
        const isOpen = !!open[o.id];
        const mine = o.vendorItems || [];
        const gross = o.vendorGross || 0;
        const earnings = o.vendorEarnings || 0;
        const commission = Math.round((gross - earnings) * 100) / 100;
        return {
          reference: o.reference,
          customer: o.customerName,
          email: o.customerEmail,
          date: new Date(o.placedAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
          statusLabel: b.label, badgeBg: b.bg, badgeInk: b.ink,
          earnings: this.money(earnings),
          grossNote: this.money(gross) + ' gross',
          payment: o.paymentMethod,
          open: isOpen,
          expanded: isOpen ? 'true' : 'false',
          chevron: isOpen ? 0 : -90,
          rowBg: isOpen ? '#FCFDFC' : '#FFFFFF',
          onToggle: () => this.setState(s => ({ open: Object.assign({}, s.open, { [o.id]: !s.open[o.id] }) })),
          items: mine.map(i => {
            const sp = plan ? this.rules.settleLine({ price: i.price, planCode: plan.code }) : null;
            return {
              title: i.title, cover: i.cover,
              href: url('product', { id: i.productId }),
              price: this.money(i.price),
              earnings: sp ? this.money(sp.vendorEarnings) : '—',
            };
          }),
          breakdown: [
            { label: 'Gross', value: this.money(gross), ink: '#29483C' },
            { label: 'Commission and fees', value: '−' + this.money(commission), ink: '#595959' },
            { label: 'Your earnings', value: this.money(earnings), ink: '#3A836B' },
            { label: 'Your items', value: mine.length + ' of ' + o.itemCount, ink: '#29483C' },
          ],
        };
      }),

      showPager: !loading && pages > 1,
      pageLabel: 'Page ' + page + ' of ' + pages,
      prevDisabled: page <= 1, nextDisabled: page >= pages,
      prevOpacity: page <= 1 ? 0.4 : 1, nextOpacity: page >= pages ? 0.4 : 1,
      onPrev: () => { if (page > 1) this.setState({ page: page - 1 }, () => this.load()); },
      onNext: () => { if (page < pages) this.setState({ page: page + 1 }, () => this.load()); },
      onStatus: e => this.setState({ status: e.target.value, page: 1 }, () => this.load()),
      onSearch: e => {
        const v = e.target.value;
        clearTimeout(this._t);
        this.setState({ query: v, page: 1 });
        this._t = setTimeout(() => this.load(), 220);
      },
    };
  }
}

