class Component extends DCLogic {
  state = {
    loading: true, user: null, stats: null, payouts: [], plan: null,
    busy: false, errors: {}, values: { amount: '', method: '' },
  };

  async componentDidMount() {
    const [app, vendors, finance, rules, validation] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/vendorsRepo.js'),
      __ulmImport('assets/js/repositories/financeRepo.js'),
      __ulmImport('assets/js/business-rules.js'),
      __ulmImport('assets/js/validation.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, vendors, finance, rules, validation });
    const user = app.auth.requireRole('vendor', 'admin');
    if (!user) return;
    this.user = user;
    this.vid = user.vendorId || (user.vendor && user.vendor.id) || 'v-1';
    this.setState({ user });
    await this.load();
  }

  async load() {
    const [st, po] = await Promise.all([
      this.vendors.vendorStats(this.vid),
      this.finance.listPayouts({ vendorId: this.vid, pageSize: 24 }),
    ]);
    const v = (this.user || this.state.user).vendor;
    this.setState({
      loading: false, stats: st.data, payouts: po.data,
      plan: this.rules.planByCode(v ? v.planCode : 'basic'),
      values: { amount: '', method: (v && v.payoutMethod) || 'PayPal' },
    });
  }

  money(n) { return '$' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, stats: s, payouts, plan, busy, errors, values, user } = this.state;
    const v = user && user.vendor;
    const hasMethod = !!(v && v.payoutMethod);
    const avail = s ? s.withdrawable : 0;

    return {
      loading,
      ready: !loading && !!s,
      subtitle: s ? 'Lifetime earnings ' + this.money(s.earnings) + ' from ' + s.unitsSold + ' sales' : '',
      setupHref: url('storeSetup'),

      stats: s ? [
        { label: 'Available to withdraw', value: this.money(s.withdrawable), note: avail >= 25 ? 'Above the $25.00 minimum' : 'Minimum is $25.00', ink: '#3A836B' },
        { label: 'Lifetime earnings', value: this.money(s.earnings), note: 'After commission and fees', ink: '#29483C' },
        { label: 'Already paid out', value: this.money(s.paidOut), note: payouts.filter(p => p.status === 'paid').length + ' completed payouts', ink: '#29483C' },
        { label: 'Gross sales', value: this.money(s.grossSales), note: 'What buyers paid in total', ink: '#29483C' },
      ] : [],

      noPayoutMethod: !hasMethod,
      canWithdraw: hasMethod,
      available: this.money(avail),
      methods: (this.rules ? this.rules.PAYOUT_METHODS : []).map(m => ({
        value: m,
        label: m + (v && v.payoutAccount && v.payoutMethod === m ? ' — ' + v.payoutAccount : ''),
      })),
      vAmount: values.amount,
      vMethod: values.method,
      amountBorder: errors.amount ? '#C0392B' : '#CAC4D0',
      amountLabelColor: errors.amount ? '#C0392B' : '#49454F',
      amountInvalid: errors.amount ? 'true' : 'false',
      amountHelp: errors.amount || 'Minimum $25.00 · available ' + this.money(avail),
      amountHelpColor: errors.amount ? '#C0392B' : '#49454F',
      busy,
      submitOpacity: busy ? 0.72 : 1,
      submitLabel: busy ? 'Requesting…' : 'Request withdrawal',
      cycleNote: this.rules ? this.rules.PAYOUT_CYCLE + '.' : '',

      historyCount: payouts.length ? payouts.length + (payouts.length === 1 ? ' payout' : ' payouts') : '',
      hasPayouts: payouts.length > 0,
      noPayouts: payouts.length === 0,
      payouts: payouts.map(p => {
        const b = BADGES[p.status] || BADGES.pending;
        return {
          period: p.period,
          method: p.method + (p.account ? ' · ' + p.account : ''),
          statusLabel: b.label, badgeBg: b.bg, badgeInk: b.ink,
          amount: this.money(p.amount),
          dates: p.paidAt
            ? 'Paid ' + new Date(p.paidAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
            : 'Requested ' + new Date(p.requestedAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
        };
      }),

      terms: plan ? [
        { label: 'Your plan', value: plan.name, note: plan.priceLabel },
        { label: 'Your payout share', value: plan.payoutRate === null ? '—' : Math.round(plan.payoutRate * 100) + '%', note: 'Of every sale' },
        { label: 'Per transaction', value: plan.transactionFee === null ? '—' : (plan.transactionFeePct ? (plan.transactionFeePct * 100).toFixed(1) + '% + ' : '') + '$' + plan.transactionFee.toFixed(2), note: 'Deducted from your share' },
        { label: 'Payout cycle', value: 'Monthly', note: 'Issued on the 5th' },
      ] : [],
      planNote: plan && plan.code !== 'premium' ? 'Premium vendors keep 80% with a $0.25 fee.' : '',

      onInput: e => {
        const { name, value } = e.target;
        this.setState(s2 => ({
          values: Object.assign({}, s2.values, { [name]: value }),
          errors: Object.assign({}, s2.errors, { [name]: null }),
        }));
      },
      onWithdraw: async e => {
        e.preventDefault();
        if (this.state.busy) return;
        const { valid, errors: errs } = this.validation.validate(this.state.values, this.validation.schemas.withdrawal);
        if (!valid) {
          this.setState({ errors: errs });
          const el = document.getElementById('vp-amount');
          if (el) el.focus();
          return;
        }
        this.setState({ busy: true });
        try {
          await this.finance.requestWithdrawal(this.vid, this.state.values);
          this.setState({ busy: false, values: { amount: '', method: this.state.values.method } });
          await this.load();
          this.app.toast('Withdrawal requested. Payouts are issued on the monthly cycle.', 'success');
        } catch (err) {
          const { message, fields } = this.app.readError(err);
          this.setState({ busy: false, errors: fields && Object.keys(fields).length ? fields : { amount: message } });
        }
      },
    };
  }
}

