class Component extends DCLogic {
  state = { user: null, vendor: null, sub: null };

  async componentDidMount() {
    const [app, finance] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/financeRepo.js'),
    ]);
    await app.boot();
    this.app = app;
    const user = app.auth.requireRole('vendor', 'admin');
    if (!user) return;
    // An approved vendor has no business on this page.
    if (user.vendor && user.vendor.status === 'approved' && user.vendor.setupComplete) {
      app.router.replace('vendorDashboard');
      return;
    }
    let sub = null;
    if (user.vendor) {
      try { sub = (await finance.getSubscription(user.vendor.id)).data; } catch (e) { sub = null; }
    }
    this.setState({ user, vendor: user.vendor || null, sub });
  }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const v = this.state.vendor;
    const sub = this.state.sub;
    const status = v ? v.status : 'pending';
    const declined = status === 'declined';
    const approved = status === 'approved';
    const suspended = status === 'suspended';

    const badge = {
      pending: { text: 'Awaiting review', bg: '#FFF2DE', ink: '#B9913E', dot: '#B9913E' },
      approved: { text: 'Approved', bg: '#EAF7F1', ink: '#3A836B', dot: '#3A836B' },
      declined: { text: 'Declined', bg: '#FDF1EF', ink: '#C0392B', dot: '#C0392B' },
      suspended: { text: 'Suspended', bg: '#FDF1EF', ink: '#C0392B', dot: '#C0392B' },
    }[status] || { text: status, bg: '#F3F4F6', ink: '#595959', dot: '#595959' };

    const heading = declined ? 'Your registration was declined'
      : suspended ? 'Your store is suspended'
      : approved ? 'Your store is approved'
      : 'Your vendor account is under review';

    const body = declined
      ? 'An administrator reviewed your registration and could not approve it as submitted. The reason is below — you are welcome to address it and get in touch.'
      : suspended
      ? 'Your store and listings are hidden from the storefront. Contact us to discuss reinstatement.'
      : approved
      ? 'Publishing is now unlocked. Complete your store setup so buyers see a finished storefront.'
      : 'An administrator is reviewing your registration against our content standard. You will receive an email as soon as a decision is made. Publishing is unavailable until your store is approved.';

    const step = n => {
      const reached = approved ? 3 : declined || suspended ? 2 : 2;
      const doneMark = n < reached;
      const current = n === reached;
      return {
        mark: doneMark ? '✓' : String(n),
        dotBg: doneMark ? '#3A836B' : current ? '#FFFFFF' : '#FFFFFF',
        dotBorder: doneMark || current ? '#3A836B' : '#DCE7E1',
        dotInk: doneMark ? '#FFFFFF' : current ? '#3A836B' : '#9AA5A0',
        titleInk: doneMark || current ? '#29483C' : '#9AA5A0',
      };
    };

    return {
      badgeText: badge.text, badgeBg: badge.bg, badgeInk: badge.ink, badgeDot: badge.dot,
      heading, body,
      submitted: v ? new Date(v.joinedAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' }) : '—',
      isDeclined: declined,
      declineReason: v ? (v.declineReason || '') : '',
      hasDeclineNote: !!(v && v.declineNote),
      declineNote: v ? (v.declineNote || '') : '',
      canSetUp: approved,
      setupHref: url('storeSetup'),
      browseHref: url('browse'),
      contactHref: url('contact'),
      timeline: [
        Object.assign({ title: 'Registration received', text: 'Your store details and plan choice are recorded.' }, step(1)),
        Object.assign({ title: 'Administrative review', text: 'We check the store against the Qur’an-and-Sunnah content standard.' }, step(2)),
        Object.assign({ title: 'Store setup', text: 'Add your branding, biography and payout details.' }, step(3)),
        Object.assign({ title: 'Publish your first resource', text: 'Each submission is approved before it appears on the storefront.' }, step(4)),
      ],
      summary: [
        { label: 'Store name', value: v ? v.storeName : '—' },
        { label: 'Plan', value: v ? (v.planName || v.planCode) : '—' },
        { label: 'Plan fee', value: sub ? (sub.planFee === null ? 'By agreement' : sub.planFee === 0 ? 'Free' : '$' + sub.planFee + '/year') : '—' },
        { label: 'First billing', value: sub ? new Date(sub.nextBillingDate).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : '—' },
        { label: 'Country', value: v ? (v.country || '—') : '—' },
      ],
    };
  }
}

