            categoryId: p.categoryId || '', subject: p.subject || '',
            gradeFrom: p.gradeFrom || '', gradeTo: p.gradeTo || '',
            resourceType: p.resourceType || '', theme: p.theme || 'Everyday',
            price: p.price ? String(p.price) : '0',
            originalPrice: p.originalPrice ? String(p.originalPrice) : '',
            fileType: p.fileType || '', pageCount: p.pageCount ? String(p.pageCount) : '',
            cover: p.cover || '', gallery: (p.gallery || []).slice(),
            fileName: p.fileName || '', fileSizeMb: p.fileSizeMb || null,
          },
        });
        return;
      } catch (err) {
        this.setState({ loading: false, user, plan, allowance, formError: 'That resource could not be found.' });
        return;
      }
    }

    // New resource — block up front if the plan has no room for a paid one.
    this.setState({
      loading: false, user, plan, allowance,
      blockedReason: !allowance.allowed && !plan.allowsPaidListings ? null : null,
      values: Object.assign({}, this.state.values, { price: plan.allowsPaidListings ? '' : '0' }),
    });
  }

  field(name) {
    const err = this.state.errors[name];
    const cap = name.charAt(0).toUpperCase() + name.slice(1);
    return {
      ['v' + cap]: this.state.values[name],
      [name + 'Error']: err || '',
      [name + 'Border']: err ? '#C0392B' : '#CAC4D0',
      [name + 'LabelColor']: err ? '#C0392B' : '#49454F',
      [name + 'Invalid']: err ? 'true' : 'false',
    };
  }

  payload() {
    const v = this.state.values;
    return {
      title: v.title.trim(),
      description: v.description.trim(),
      included: v.included.split('\n').map(s => s.trim()).filter(Boolean),
      categoryId: v.categoryId, subject: v.subject,
      gradeFrom: v.gradeFrom, gradeTo: v.gradeTo,
      resourceType: v.resourceType, theme: v.theme,
      price: v.price === '' ? 0 : Number(v.price),
      originalPrice: v.originalPrice === '' ? null : Number(v.originalPrice),
      fileType: v.fileType,
      pageCount: v.pageCount === '' ? null : Number(v.pageCount),
      cover: v.cover || (v.gallery[0] || 'assets/img/cover-1.jpg'),
      gallery: v.gallery.slice(),
      fileName: v.fileName || null,
      fileSizeMb: v.fileSizeMb,
      tags: [],
    };
  }

  async persist(mode) {
    const { valid, errors } = this.validation.validate(this.state.values, this.validation.schemas.product);
    if (mode === 'submit' && !valid) {
      this.setState({ errors });
      const el = document.getElementById('pe-' + Object.keys(errors)[0]);
      if (el) el.focus();
      return;
    }
    this.setState({ busy: true, formError: '' });
    try {
      const body = this.payload();
      let saved;
      if (this.state.product) {
        const res = await this.repo.updateProduct(this.state.product.id, body);
        saved = res.data;
      } else {
        const res = await this.repo.createProduct(this.vid, body);
        saved = res.data;
      }
      if (mode === 'submit' && saved.status !== 'pending') {
        await this.repo.submitProduct(saved.id);
      }
      this.app.toast(
        mode === 'submit'
          ? 'Submitted for review. You will be notified once a decision is made.'
          : 'Draft saved.',
        'success'
      );
      this.app.router.go('vendorProducts');
    } catch (err) {
      const { message, fields } = this.app.readError(err);
      this.setState({ busy: false, formError: message, errors: fields || {} });
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, product, busy, errors, formError, values, plan, allowance, blockedReason } = this.state;
    const cat = this.rules && values.categoryId ? this.rules.categoryById(values.categoryId) : null;
    const freeOnly = !!(plan && !plan.allowsPaidListings);
    const price = values.price === '' ? 0 : Number(values.price) || 0;
    const split = plan && price > 0 ? this.rules.settleLine({ price, planCode: plan.code }) : null;
    const status = product ? product.status : 'draft';
    const titleLen = values.title.length;
    const descLen = values.description.length;

    const check = (ok, text) => ({
      mark: ok ? '✓' : '·',
      bg: ok ? '#EAF7F1' : '#F3F4F6',
      ink: ok ? '#3A836B' : '#9AA5A0',
      textInk: ok ? '#121212' : '#9AA5A0',
      text,
    });

    return Object.assign({
      loading,
      blocked: !!blockedReason,
      editable: !loading && !blockedReason,
      pageTitle: product ? 'Edit resource' : 'New resource',
      subtitle: product ? product.title : 'Every submission is reviewed before it goes live.',
      productsHref: url('vendorProducts'),

      blockedTitle: 'Publishing is not available yet',
      blockedBody: 'Your store is still with an administrator for review. Once it is approved you can create and submit resources.',
      blockedCta: 'See my approval status',
      blockedHref: url('vendorPending'),

      hasError: !!formError,
      formError,

      showDeclineNote: status === 'declined',
      declineReason: product ? (product.declineReason || '') : '',
      hasDeclineDetail: !!(product && product.declineNote),
      declineNote: product ? (product.declineNote || '') : '',
      showReapprovalNote: status === 'approved',

      categories: this.rules ? this.rules.CATEGORIES.map(c => ({ id: c.id, name: c.name })) : [],
      subjects: cat ? cat.subjects.map(value => ({ value })) : [],
      noCategory: !values.categoryId,
      subjectBg: values.categoryId ? '#FFFFFF' : '#F5F7F6',
      subjectCursor: values.categoryId ? 'pointer' : 'not-allowed',
      subjectPlaceholder: values.categoryId ? 'Choose a subject…' : 'Pick a category first',
      grades: this.rules ? this.rules.GRADES.map(value => ({ value })) : [],
      resourceTypes: this.rules ? this.rules.RESOURCE_TYPES.map(value => ({ value })) : [],
      themes: this.rules ? this.rules.THEMES.map(value => ({ value })) : [],
      fileTypes: this.rules ? this.rules.FILE_TYPES.map(value => ({ value })) : [],

      titleHelp: errors.title || titleLen + ' / 120 characters — at least 10.',
      titleHelpColor: errors.title ? '#C0392B' : '#49454F',
      descriptionHelp: errors.description || descLen + ' characters — at least 80.',
      descriptionHelpColor: errors.description ? '#C0392B' : '#49454F',

      fileName: values.fileName || 'No file attached',
      fileHint: values.fileSizeMb ? values.fileSizeMb + ' MB · buyers download this file' : 'PDF, ZIP or PowerPoint, up to 25 MB',
      fileCta: values.fileName ? 'Replace' : 'Attach file',
      fileBorder: errors.file ? '#C0392B' : '#DCE7E1',
      fileLabelColor: errors.file ? '#C0392B' : '#49454F',

      gallery: values.gallery.map((src, i) => ({
        src, isCover: i === 0,
        border: i === 0 ? '#3A836B' : 'transparent',
        removeLabel: 'Remove preview image ' + (i + 1),
        onRemove: () => this.setState(s => {
          const g = s.values.gallery.slice();
          g.splice(i, 1);
          return { values: Object.assign({}, s.values, { gallery: g, cover: g[0] || '' }) };
        }),
      })),
      canAddImage: values.gallery.length < 5,

      freeOnly,
      priceBg: freeOnly ? '#F5F7F6' : '#FFFFFF',
      priceHelp: errors.price
        || (freeOnly ? 'Fixed at free on your plan.'
          : allowance && allowance.limit ? 'Paid slots used: ' + allowance.used + ' of ' + allowance.limit
          : 'Leave at 0 to publish this resource free.'),
      priceHelpColor: errors.price ? '#C0392B' : '#49454F',

      showSplit: !!split,
      split: split ? [
        { label: 'Buyer pays', value: '$' + split.gross.toFixed(2), weight: 500, ink: '#29483C' },
        { label: 'Platform commission', value: '−$' + split.commission.toFixed(2), weight: 500, ink: '#595959' },
        { label: 'Transaction fee', value: '−$' + split.transactionFee.toFixed(2), weight: 500, ink: '#595959' },
        { label: 'You receive', value: '$' + split.vendorEarnings.toFixed(2), weight: 700, ink: '#3A836B' },
      ] : [],
      splitNote: plan ? plan.name + ' — ' + Math.round((plan.payoutRate || 0) * 100) + '% payout, fee deducted from your share.' : '',

      statusDot: ({ approved: '#3A836B', pending: '#B9913E', draft: '#2F7FA0', declined: '#C0392B', unpublished: '#595959' })[status] || '#2F7FA0',
      statusLabel: ({ approved: 'Published', pending: 'In review', draft: 'Draft', declined: 'Declined', unpublished: 'Unpublished' })[status] || 'Draft',
      statusBlurb: status === 'approved'
        ? 'Live on the storefront. An edit returns it to the review queue.'
        : status === 'pending'
          ? 'An administrator is reviewing this submission.'
          : status === 'declined'
            ? 'Address the reason above, then submit again.'
            : 'Not visible to anyone yet. Save a draft as often as you like.',

      busy,
      submitOpacity: busy ? 0.72 : 1,
      submitLabel: busy ? 'Saving…' : status === 'approved' ? 'Save and resubmit' : 'Submit for review',
      draftLabel: 'Save draft',

      checklist: [
        check(titleLen >= 10, 'A clear title of at least 10 characters'),
        check(descLen >= 80, 'A description of at least 80 characters'),
        check(!!values.categoryId && !!values.subject, 'Category and subject chosen'),
        check(!!values.gradeFrom && !!values.gradeTo, 'Grade range set'),
        check(!!values.fileName, 'The resource file attached'),
        check(values.gallery.length > 0, 'At least one preview image'),
      ],

      onInput: e => {
        const { name, value } = e.target;
        this.setState(s => ({
          values: Object.assign({}, s.values, { [name]: value }),
          errors: Object.assign({}, s.errors, { [name]: null }),
          formError: '',
        }));
      },
      onCategory: e => {
        const value = e.target.value;
        this.setState(s => ({
          values: Object.assign({}, s.values, { categoryId: value, subject: '' }),
          errors: Object.assign({}, s.errors, { categoryId: null, subject: null }),
        }));
      },
      onFile: async e => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const mb = Math.round((file.size / (1024 * 1024)) * 100) / 100;
        if (mb > 25) {
          this.setState(s => ({ errors: Object.assign({}, s.errors, { file: 'That file is ' + mb + ' MB. The limit is 25 MB.' }) }));
          return;
        }
        this.setState(s => ({
          values: Object.assign({}, s.values, { fileName: file.name, fileSizeMb: mb }),
          errors: Object.assign({}, s.errors, { file: null }),
        }));
        this.app.toast('File attached: ' + file.name, 'success');
      },
      onImage: async e => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const dataUrl = await this.db.fileToDataUrl(file);
        this.setState(s => {
          const g = s.values.gallery.concat([dataUrl]).slice(0, 5);
          return { values: Object.assign({}, s.values, { gallery: g, cover: g[0] }) };
        });
      },
      onSaveDraft: () => this.persist('draft'),
      onSubmitForReview: e => { e.preventDefault(); this.persist('submit'); },
    }, this.field('title'), this.field('description'), this.field('included'),
       this.field('categoryId'), this.field('subject'), this.field('gradeFrom'),
       this.field('gradeTo'), this.field('resourceType'), this.field('theme'),
       this.field('price'), this.field('originalPrice'), this.field('fileType'),
       this.field('pageCount'));
  }
}

Vendor Products.j:
const BADGES = {
  approved: { bg: '#EAF7F1', ink: '#3A836B', label: 'Published' },
  pending: { bg: '#FFF2DE', ink: '#B9913E', label: 'In review' },
  draft: { bg: '#E3F7FD', ink: '#2F7FA0', label: 'Draft' },
  declined: { bg: '#FDF1EF', ink: '#C0392B', label: 'Declined' },
  unpublished: { bg: '#F3F4F6', ink: '#595959', label: 'Unpublished' },
};

class Component extends DCLogic {
  state = { loading: true, rows: [], meta: null, user: null, status: '', query: '', page: 1, counts: {}, allowance: null };

  async componentDidMount() {
    const [app, products, db] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/productsRepo.js'),
      __ulmImport('assets/js/db.js'),
    ]);
    await app.boot();
    this.app = app; this.repo = products; this.db = db;
    const user = app.auth.requireRole('vendor', 'admin');
    if (!user) return;
    this.vid = user.vendorId || (user.vendor && user.vendor.id) || 'v-1';
    this.setState({ user, status: app.router.param('status', '') || '' });
    await this.load();
  }

  async load() {
    this.setState({ loading: true });
    const res = await this.repo.listProducts({
      vendorId: this.vid,
      status: this.state.status || 'any',
      q: this.state.query,
      page: this.state.page, pageSize: 10,
      sort: 'newest',
    });
    const all = this.db.findAll('products', { filter: { vendorId: this.vid } }).rows;
    this.setState({
      loading: false, rows: res.data, meta: res.meta,
      allowance: this.repo.checkAllowance(this.vid),
      counts: {
        all: all.length,
        approved: all.filter(p => p.status === 'approved').length,
        pending: all.filter(p => p.status === 'pending').length,
        draft: all.filter(p => p.status === 'draft').length,
        declined: all.filter(p => p.status === 'declined').length,
      },
    });
  }

  set(patch) { this.setState(patch, () => this.load()); }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, rows, meta, status, query, page, counts, allowance } = this.state;
    const pages = meta ? meta.totalPages : 1;
    const a = allowance;

    return {
      subtitle: counts.all ? counts.all + ' resources · ' + counts.approved + ' live on the storefront' : '',
      newProductHref: url('vendorProductEdit'),
      subscriptionHref: url('vendorSubscription'),
      loading, query,

      showCapNotice: !!(a && !a.allowed),
      capNotice: a && a.reason === 'plan_free_no_paid_listings'
        ? 'The Pioneer Vendor plan does not permit paid listings. You can publish unlimited free resources, or upgrade to Basic or Premium to sell.'
        : a && a.limit
          ? 'You have used all ' + a.limit + ' paid resource slots on your plan. Upgrade to Premium for unlimited uploads.'
          : '',

      tabs: [
        { key: '', label: 'All', n: counts.all },
        { key: 'approved', label: 'Published', n: counts.approved },
        { key: 'pending', label: 'In review', n: counts.pending },
        { key: 'draft', label: 'Drafts', n: counts.draft },
        { key: 'declined', label: 'Declined', n: counts.declined },
      ].map(t => {
        const on = t.key === status;
        return {
          label: t.label,
          count: String(t.n || 0),
          pressed: on ? 'true' : 'false',
          bg: on ? '#3A836B' : '#FFFFFF',
          border: on ? '#3A836B' : '#E9EFEC',
          ink: on ? '#FFFFFF' : '#29483C',
          pillBg: on ? 'rgba(255,255,255,.22)' : '#F1F4F2',
          pillInk: on ? '#FFFFFF' : '#595959',
          onPick: () => this.set({ status: t.key, page: 1 }),
        };
      }),

      isEmpty: !loading && rows.length === 0,
      hasRows: !loading && rows.length > 0,
      emptyTitle: query || status ? 'Nothing matches that view' : 'You have not created a resource yet',
      emptyBody: query || status
        ? 'Try clearing the search or choosing a different status.'
        : 'Add your first resource, attach the file, and submit it for review.',

      rows: rows.map(p => {
        const b = BADGES[p.status] || BADGES.draft;
        return {
          title: p.title,
          cover: p.cover,
          editHref: url('vendorProductEdit', { id: p.id }),
          badgeText: b.label, badgeBg: b.bg, badgeInk: b.ink,
          meta: [p.categoryName, p.gradeLabel, p.resourceType].filter(Boolean).join(' · '),
          price: p.price ? '$' + p.price.toFixed(2) : 'Free',
          downloads: (p.downloads || 0).toLocaleString('en-US') + ' downloads',
          hasDecline: p.status === 'declined' && !!p.declineReason,
          declineReason: p.declineReason || '',
          canSubmit: p.status === 'draft' || p.status === 'declined',
          editLabel: 'Edit ' + p.title,
          dupLabel: 'Duplicate ' + p.title,
          delLabel: 'Delete ' + p.title,
          onSubmit: async () => {
            await this.repo.submitProduct(p.id);
            await this.load();
            this.app.toast('Submitted for review. You will be notified once a decision is made.', 'success');
          },
          onDuplicate: async () => {
            await this.repo.duplicateProduct(p.id);
            await this.load();
            this.app.toast('Product duplicated as a new draft.', 'success');
          },
          onDelete: async () => {
            const ok = await this.app.confirmDialog({
              title: 'Delete this product?',
              body: 'Purchasers keep their download access; the listing is removed from the storefront.',
              confirmLabel: 'Delete product',
            });
            if (!ok) return;
            await this.repo.deleteProduct(p.id);
            await this.load();
            this.app.toast('Product deleted.', 'success');
          },
        };
      }),

      showPager: !loading && pages > 1,
      pageLabel: 'Page ' + page + ' of ' + pages,
      prevDisabled: page <= 1, nextDisabled: page >= pages,
      prevOpacity: page <= 1 ? 0.4 : 1, nextOpacity: page >= pages ? 0.4 : 1,
      onPrev: () => { if (page > 1) this.set({ page: page - 1 }); },
      onNext: () => { if (page < pages) this.set({ page: page + 1 }); },
      onSearch: e => {
        const v = e.target.value;
        clearTimeout(this._t);
        this.setState({ query: v, page: 1 });
        this._t = setTimeout(() => this.load(), 220);
      },
    };
  }
}

