class Component extends DCLogic {
  state = { loading: true, user: null, stats: null, plan: null };

  async componentDidMount() {
    const [app, vendors, rules, db] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/vendorsRepo.js'),
      __ulmImport('assets/js/business-rules.js'),
      __ulmImport('assets/js/db.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, vendors, rules, db });
    const user = app.auth.requireRole('vendor', 'admin');
    if (!user) return;
    this.vid = user.vendorId || (user.vendor && user.vendor.id) || 'v-1';
    const st = await vendors.vendorStats(this.vid);
    this.setState({
      loading: false, user, stats: st.data,
      plan: rules.planByCode(user.vendor ? user.vendor.planCode : 'basic'),
    });
  }

  money(n) { return '$' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, stats: s, plan } = this.state;
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const max = s && s.byMonth.length ? Math.max.apply(null, s.byMonth.map(m => m.gross)) : 0;
    const topMax = s && s.topProducts.length ? Math.max.apply(null, s.topProducts.map(p => p.revenue)) : 0;
    const gross = s ? s.grossSales : 0;
    const pct = v => gross ? Math.round(v / gross * 100) : 0;

    return {
      loading,
      ready: !loading && !!s,
      subtitle: s ? 'Derived from ' + s.ordersReceived + ' orders across ' + s.byMonth.length + ' months' : '',

      stats: s ? [
        { label: 'Gross sales', value: this.money(s.grossSales), note: s.unitsSold + ' resources sold' },
        { label: 'Your earnings', value: this.money(s.earnings), note: pct(s.earnings) + '% of gross' },
        { label: 'Average order', value: this.money(s.ordersReceived ? s.grossSales / s.ordersReceived : 0), note: 'Across your items' },
        { label: 'Distinct buyers', value: String(s.customerCount), note: s.followers + ' followers' },
      ] : [],

      hasChart: !!(s && s.byMonth.length),
      noChart: !!(s && !s.byMonth.length),
      chart: s ? s.byMonth.map(m => {
        const d = new Date(m.month + '-01');
        return {
          label: monthNames[d.getMonth()],
          gross: '$' + Math.round(m.gross),
          grossPct: max ? Math.round(m.gross / max * 100) : 0,
          earnPct: max ? Math.round(m.earnings / max * 100) : 0,
          grossTip: 'Gross ' + this.money(m.gross),
          earnTip: 'You earned ' + this.money(m.earnings),
        };
      }) : [],

      hasTop: !!(s && s.topProducts.length),
      noTop: !!(s && !s.topProducts.length),
      topProducts: s ? s.topProducts.map(t => ({
        title: t.title.length > 46 ? t.title.slice(0, 44).trim() + '…' : t.title,
        href: url('product', { id: t.productId }),
        units: String(t.units),
        revenue: this.money(t.revenue),
        pct: topMax ? Math.round(t.revenue / topMax * 100) : 0,
        pctLabel: pct(t.revenue) + '%',
      })) : [],

      splitRows: s ? [
        { label: 'Your earnings', value: this.money(s.earnings), pct: pct(s.earnings), fill: '#3A836B', ink: '#3A836B' },
        { label: 'Platform commission', value: this.money(s.commission), pct: pct(s.commission), fill: '#FEDC97', ink: '#29483C' },
        { label: 'Transaction fees', value: this.money(s.transactionFees), pct: pct(s.transactionFees), fill: '#C9C9C9', ink: '#595959' },
      ] : [],
      planNote: plan
        ? plan.name + ' keeps ' + Math.round((plan.payoutRate || 0) * 100) + '% of each sale, with the per-transaction fee taken from your share.'
        : '',

      reach: s ? [
        { label: 'Published resources', value: String(s.productCount), note: s.pendingCount + ' awaiting review' },
        { label: 'Drafts', value: String(s.draftCount), note: 'Not visible to buyers' },
        { label: 'Declined', value: String(s.declinedCount), note: 'Awaiting your changes' },
        { label: 'Already paid out', value: this.money(s.paidOut), note: this.money(s.withdrawable) + ' available now' },
      ] : [],
    };
  }
}

