class Component extends DCLogic {
  state = {
    loading: true, user: null, vendor: null, stats: null, busy: false, saved: false,
    errors: {}, formError: '',
    values: { storeName: '', slug: '', bio: '', country: '', logo: null, banner: null, payoutMethod: 'PayPal', payoutAccount: '' },
  };

  async componentDidMount() {
    const [app, vendors, rules, validation, db] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/vendorsRepo.js'),
      __ulmImport('assets/js/business-rules.js'),
      __ulmImport('assets/js/validation.js'),
      __ulmImport('assets/js/db.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, vendors, rules, validation, db });
    const user = app.auth.requireRole('vendor', 'admin');
    if (!user) return;
    this.vid = user.vendorId || (user.vendor && user.vendor.id) || 'v-1';
    const [v, st] = await Promise.all([
      vendors.getVendor(this.vid),
      vendors.vendorStats(this.vid).catch(() => ({ data: null })),
    ]);
    const d = v.data;
    this.setState({
      loading: false, user, vendor: d, stats: st.data,
      values: {
        storeName: d.storeName || '', slug: d.slug || '', bio: d.bio || '',
        country: d.country || 'United States',
        logo: d.logo || null, banner: d.banner || null,
        payoutMethod: d.payoutMethod || 'PayPal', payoutAccount: d.payoutAccount || '',
      },
    });
  }

  field(name) {
    const err = this.state.errors[name];
    const cap = name.charAt(0).toUpperCase() + name.slice(1);
    return {
      ['v' + cap]: this.state.values[name],
      [name + 'Error']: err || '',
      [name + 'Border']: err ? '#C0392B' : '#CAC4D0',
      [name + 'LabelColor']: err ? '#C0392B' : '#49454F',
      [name + 'Invalid']: err ? 'true' : 'false',
    };
  }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, vendor, stats, busy, saved, errors, formError, values } = this.state;
    const bioLen = (values.bio || '').length;
    const initials = (values.storeName || '?').split(/\s+/).slice(0, 2).map(w => w[0]).join('').toUpperCase();

    return Object.assign({
      loading,
      ready: !loading && !!vendor,
      subtitle: vendor ? 'Public at /store/' + vendor.slug : '',
      storefrontHref: vendor ? url('vendorStore', { store: values.slug || vendor.slug }) : '#',

      hasError: !!formError,
      formError,
      hasLogo: !!values.logo, noLogo: !values.logo,
      hasBanner: !!values.banner, noBanner: !values.banner,
      logoCta: values.logo ? 'Replace logo' : 'Choose logo',
      bannerCta: values.banner ? 'Replace banner' : 'Choose banner',
      initials,

      bioHelp: errors.bio || bioLen + ' / 600 characters — at least 40.',
      bioHelpColor: errors.bio ? '#C0392B' : '#49454F',

      countries: ['United States', 'United Kingdom', 'Canada', 'Australia', 'Pakistan', 'Nigeria', 'United Arab Emirates', 'Malaysia', 'South Africa', 'Other'].map(value => ({ value })),

      payoutOptions: (this.rules ? this.rules.PAYOUT_METHODS : []).map(value => {
        const on = values.payoutMethod === value;
        return {
          value, checked: on,
          bg: on ? '#F2FAF7' : '#FFFFFF',
          border: on ? '#3A836B' : '#EDF0EE',
          dotBg: on ? '#3A836B' : '#FFFFFF',
          dotBorder: on ? '#3A836B' : '#CAC4D0',
          dotInner: on ? 'inset 0 0 0 3px #FFFFFF' : 'none',
          onPick: () => this.setState(s => ({ values: Object.assign({}, s.values, { payoutMethod: value }) })),
        };
      }),
      payoutAccountLabel: values.payoutMethod === 'PayPal' ? 'PayPal email' : 'Bank account details',

      previewName: values.storeName || 'Your store',
      previewMeta: stats
        ? [stats.productCount + ' resources', vendor.followers + ' followers'].join(' · ')
        : '',
      previewBio: values.bio || 'Your biography appears here.',

      busy, saved,
      submitOpacity: busy ? 0.72 : 1,
      submitLabel: busy ? 'Saving…' : 'Save store profile',

      onInput: e => {
        const { name, value } = e.target;
        this.setState(s => ({
          values: Object.assign({}, s.values, { [name]: value }),
          errors: Object.assign({}, s.errors, { [name]: null }),
          formError: '', saved: false,
        }));
      },
      onLogo: async e => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const logo = await this.db.fileToDataUrl(file);
        this.setState(s => ({ values: Object.assign({}, s.values, { logo }), saved: false }));
      },
      onBanner: async e => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const banner = await this.db.fileToDataUrl(file);
        this.setState(s => ({ values: Object.assign({}, s.values, { banner }), saved: false }));
      },
      onClearLogo: () => this.setState(s => ({ values: Object.assign({}, s.values, { logo: null }), saved: false })),
      onClearBanner: () => this.setState(s => ({ values: Object.assign({}, s.values, { banner: null }), saved: false })),

      onSubmit: async e => {
        e.preventDefault();
        if (this.state.busy) return;
        const { valid, errors: errs } = this.validation.validate(this.state.values, this.validation.schemas.storeProfile);
        if (!valid) {
          this.setState({ errors: errs });
          const el = document.getElementById('vs-' + Object.keys(errs)[0]);
          if (el) el.focus();
          return;
        }
        this.setState({ busy: true, formError: '' });
        try {
          await this.vendors.updateVendor(this.vid, Object.assign({}, this.state.values, { setupComplete: true }));
          this.setState({ busy: false, saved: true });
          this.app.toast('Store profile saved.', 'success');
        } catch (err) {
          const { message, fields } = this.app.readError(err);
          this.setState({ busy: false, formError: message, errors: fields || {} });
        }
      },
    }, this.field('storeName'), this.field('slug'), this.field('bio'),
       this.field('country'), this.field('payoutMethod'), this.field('payoutAccount'));
  }
}

