class Component extends DCLogic {
  state = { loading: true, vendor: null, stats: null, products: [], user: null, following: false, sort: 'newest' };

  async componentDidMount() {
    const [app, vendors, products, users, cart] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/vendorsRepo.js'),
      __ulmImport('assets/js/repositories/productsRepo.js'),
      __ulmImport('assets/js/repositories/usersRepo.js'),
      __ulmImport('assets/js/repositories/cartRepo.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, vendorsRepo: vendors, productsRepo: products, usersRepo: users, cartRepo: cart });

    const slug = app.router.param('store');
    try {
      const v = slug
        ? await vendors.getVendorBySlug(slug)
        : await vendors.getVendor('v-1');
      const user = app.auth.currentUser();
      const [st, list, follows] = await Promise.all([
        vendors.vendorStats(v.data.id).catch(() => ({ data: null })),
        products.listProducts({ vendorId: v.data.id, status: 'approved', pageSize: 24, sort: 'newest' }),
        user ? vendors.listFollowing(user.id) : Promise.resolve({ data: [] }),
      ]);
      this.setState({
        loading: false, vendor: v.data, stats: st.data, products: list.data, user,
        following: follows.data.some(f => f.id === v.data.id),
      });
      document.title = v.data.storeName + ' — Uloominate';
    } catch (err) {
      this.app.router.replace('notFound');
    }
  }

  async reload() {
    const list = await this.productsRepo.listProducts({
      vendorId: this.state.vendor.id, status: 'approved', pageSize: 24, sort: this.state.sort,
    });
    this.setState({ products: list.data });
  }

  stars(n) {
    const f = Math.round(Number(n) || 0);
    return '★'.repeat(f) + '☆'.repeat(Math.max(0, 5 - f));
  }

  decorate(p) {
    const url = this.app.router.url;
    const user = (this.user || this.state.user);
    const saved = user ? this.usersRepo.isWishlisted(user.id, p.id) : false;
    const free = !p.price;
    return {
      id: p.id,
      title: p.title,
      cover: p.cover,
      href: url('product', { id: p.id }),
      meta: [p.categoryName, p.gradeLabel].filter(Boolean).join(' · '),
      stars: this.stars(p.ratingAvg),
      ratingLabel: p.ratingCount ? '(' + p.ratingCount.toLocaleString('en-US') + ')' : '(new)',
      priceLabel: free ? 'Free' : '$' + p.price.toFixed(2),
      hasOriginal: !!p.originalPrice && !free,
      originalLabel: p.originalPrice ? '$' + p.originalPrice.toFixed(2) : '',
      hasBadge: !!p.discountPct || free,
      badgeText: p.discountPct ? p.discountPct + '% off' : 'Free',
      badgeBg: p.discountPct ? '#FEDC97' : '#3A836B',
      badgeInk: p.discountPct ? '#121212' : '#FFFFFF',
      heartColor: saved ? '#C0392B' : '#29483C',
      heartFill: saved ? '#C0392B' : 'none',
      wishPressed: saved ? 'true' : 'false',
      wishLabel: (saved ? 'Remove from wishlist: ' : 'Save to wishlist: ') + p.title,
      addText: free ? 'Get' : 'Add',
      addLabel: (free ? 'Get ' : 'Add to cart: ') + p.title,
      onWishlist: async () => {
        const u = this.app.auth.currentUser();
        if (!u) { this.app.toast('Sign in to save resources to your wishlist.', 'info'); return; }
        const res = await this.usersRepo.toggleWishlist(u.id, p.id);
        this.app.toast(res.data.saved ? 'Saved to your wishlist.' : 'Removed from your wishlist.', 'success');
        await this.reload();
      },
      onAdd: async () => {
        try {
          const u = this.app.auth.currentUser();
          await this.cartRepo.addToCart(this.cartRepo.cartOwner(u), p.id, { isCustomer: !!u });
          this.app.toast('Added to cart.', 'success');
        } catch (err) {
          this.app.toast(this.app.readError(err).message, 'error');
        }
      },
    };
  }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, vendor: v, stats, products, following, sort } = this.state;

    return {
      loading,
      ready: !loading && !!v,
      browseHref: url('browse'),
      storeName: v ? v.storeName : '',
      planName: v ? (v.planName || '') : '',
      logo: v ? v.logo : null,
      hasLogo: !!(v && v.logo),
      noLogo: !(v && v.logo),
      banner: v ? v.banner : null,
      hasBanner: !!(v && v.banner),
      initials: v ? (v.storeName || '?').split(/\s+/).slice(0, 2).map(w => w[0]).join('').toUpperCase() : '',
      bio: v ? v.bio : '',
      hasBio: !!(v && v.bio),
      meta: v
        ? [
            v.owner,
            (v.productCount || 0) + (v.productCount === 1 ? ' resource' : ' resources'),
            'joined ' + new Date(v.joinedAt).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' }),
          ].join(' · ')
        : '',

      stats: v ? [
        { label: 'Published resources', value: String(v.productCount || 0) },
        { label: 'Followers', value: String(v.followers || 0) },
        { label: 'Total downloads', value: stats ? (stats.unitsSold + products.reduce((a, p) => a + (p.downloads || 0), 0)).toLocaleString('en-US') : '—' },
        { label: 'Country', value: v.country || '—' },
      ] : [],

      followPressed: following ? 'true' : 'false',
      followLabel: following ? 'Following' : 'Follow this vendor',
      followBg: following ? '#F2FAF7' : '#3A836B',
      followInk: following ? '#29483C' : '#FFFFFF',
      followBorder: following ? '#3A836B' : '#3A836B',
      followFill: following ? '#C0392B' : 'none',
      onFollow: async () => {
        const user = this.app.auth.currentUser();
        if (!user) { this.app.toast('Sign in to follow a vendor.', 'info'); return; }
        const res = await this.vendorsRepo.toggleFollow(v.id, user.id);
        const fresh = await this.vendorsRepo.getVendor(v.id);
        this.setState({ following: res.data.following, vendor: fresh.data });
        this.app.toast(res.data.following ? 'You now follow ' + v.storeName + '.' : 'You no longer follow ' + v.storeName + '.', 'success');
      },

      catalogueHeading: products.length
        ? products.length + (products.length === 1 ? ' resource' : ' resources')
        : 'Resources',
      sort,
      onSort: e => this.setState({ sort: e.target.value }, () => this.reload()),

      hasProducts: !loading && products.length > 0,
      noProducts: !loading && products.length === 0,
      emptyBody: v && v.status !== 'approved'
        ? 'This store is not currently active.'
        : 'This vendor has not published anything yet. Follow them to hear when they do.',
      products: this.app ? products.map(p => this.decorate(p)) : [],
    };
  }
}

