class Component extends DCLogic {
  state = { loading: true, user: null, sub: null, plans: [], allowance: null };

  async componentDidMount() {
    const [app, finance, products, rules] = await Promise.all([
      __ulmImport('assets/js/app.js'),
      __ulmImport('assets/js/repositories/financeRepo.js'),
      __ulmImport('assets/js/repositories/productsRepo.js'),
      __ulmImport('assets/js/business-rules.js'),
    ]);
    await app.boot();
    Object.assign(this, { app, finance, products, rules });
    const user = app.auth.requireRole('vendor', 'admin');
    if (!user) return;
    this.vid = user.vendorId || (user.vendor && user.vendor.id) || 'v-1';
    this.setState({ user, plans: rules.PLANS });
    await this.load();
  }

  async load() {
    try {
      const sub = await this.finance.getSubscription(this.vid);
      this.setState({
        loading: false, sub: sub.data,
        allowance: this.products.checkAllowance(this.vid),
      });
    } catch (err) {
      this.setState({ loading: false });
    }
  }

  renderVals() {
    const url = this.app ? this.app.router.url : (() => '#');
    const { loading, sub, plans, allowance } = this.state;
    const current = sub ? this.rules.planByCode(sub.planCode) : null;
    const days = sub ? Math.max(0, Math.ceil((new Date(sub.promoFreeUntil).getTime() - Date.now()) / 86400000)) : 0;
    const fmtDate = d => new Date(d).toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' });

    const statusMap = {
      active: { bg: '#EAF7F1', ink: '#3A836B', label: 'Active' },
      pending: { bg: '#FFF2DE', ink: '#B9913E', label: 'Pending approval' },
      cancelled: { bg: '#FDF1EF', ink: '#C0392B', label: 'Cancelled' },
    };
    const st = sub ? (statusMap[sub.status] || statusMap.active) : statusMap.active;

    return {
      loading,
      ready: !loading && !!sub,
      subtitle: current ? current.name + ' · ' + current.priceLabel : '',
      contactHref: url('contact'),

      promoTitle: 'Founding Vendor Promotion',
      promoBody: sub ? 'Free until ' + fmtDate(sub.promoFreeUntil) + '. Billing begins ' + fmtDate(sub.promoBillingStarts) + '.' : '',
      daysLeft: String(days),

      currentName: current ? current.name : '—',
      currentPrice: current ? current.priceLabel : '—',
      statusLabel: st.label, statusBg: st.bg, statusInk: st.ink,
      isActive: !!(sub && sub.status === 'active'),
      isCancelled: !!(sub && sub.status === 'cancelled'),

      facts: sub && current ? [
        { label: 'Paid uploads', value: current.paidUploadLimit === null ? 'Unlimited' : allowance ? allowance.used + ' of ' + current.paidUploadLimit : String(current.paidUploadLimit) },
        { label: 'Your payout share', value: current.payoutRate === null ? '—' : Math.round(current.payoutRate * 100) + '%' },
        { label: 'Per transaction', value: current.transactionFee === null ? '—' : (current.transactionFeePct ? (current.transactionFeePct * 100).toFixed(1) + '% + ' : '') + '$' + current.transactionFee.toFixed(2) },
        { label: 'Next billing date', value: fmtDate(sub.nextBillingDate) },
        { label: 'Next amount', value: sub.nextBillingAmount === null ? 'By agreement' : sub.nextBillingAmount === 0 ? 'Free' : '$' + sub.nextBillingAmount },
        { label: 'Payment method', value: sub.paymentMethod || 'Not set' },
      ] : [],

      cardCta: sub && sub.paymentMethod ? 'Update payment method' : 'Add a payment method',

      plans: plans.map(p => {
        const isCurrent = !!(sub && p.code === sub.planCode);
        const byAgreement = !p.selfService;
        return {
          name: p.name,
          price: p.priceLabel,
          features: p.features.slice(0, 4).map(text => ({ text })),
          isCurrent,
          byAgreement: byAgreement && !isCurrent,
          selectable: !isCurrent && !byAgreement,
          border: isCurrent ? '#3A836B' : '#E9EFEC',
          opacity: byAgreement && !isCurrent ? 0.82 : 1,
          cta: current && p.annualFee !== null && current.annualFee !== null && p.annualFee > current.annualFee
            ? 'Upgrade to ' + p.name.split(' ')[0]
            : 'Switch to ' + p.name.split(' ')[0],
          onChoose: async () => {
            const ok = await this.app.confirmDialog({
              title: 'Switch to ' + p.name + '?',
              body: 'Your new entitlements apply immediately. Under the founding promotion nothing is charged until '
                + (sub ? fmtDate(sub.promoBillingStarts) : 'billing begins') + '.',
              confirmLabel: 'Switch plan',
              tone: 'primary',
            });
            if (!ok) return;
            try {
              await this.finance.changePlan(this.vid, p.code);
              await this.load();
              this.app.toast('Plan updated. Your new entitlements apply immediately.', 'success');
              setTimeout(() => window.location.reload(), 700);
            } catch (err) {
              this.app.toast(this.app.readError(err).message, 'error');
            }
          },
        };
      }),

      timeline: [
        {
          when: 'NOW', title: 'Founding promotion', text: 'Every plan is free. Build your catalogue and start earning.',
          mark: '✓', dotBg: '#3A836B', dotBorder: '#3A836B', dotInk: '#FFFFFF', line: '#3A836B', titleInk: '#29483C',
        },
        {
          when: sub ? fmtDate(sub.promoFreeUntil).toUpperCase() : '', title: 'Promotion ends', text: 'You will receive 30 days notice before any charge is made.',
          mark: '2', dotBg: '#FFFFFF', dotBorder: '#3A836B', dotInk: '#3A836B', line: '#DCE7E1', titleInk: '#29483C',
        },
        {
          when: sub ? fmtDate(sub.promoBillingStarts).toUpperCase() : '', title: 'Billing begins', text: sub && sub.nextBillingAmount ? 'Your ' + (current ? current.name : 'plan') + ' renews at $' + sub.nextBillingAmount + ' a year.' : 'Free plans are never charged.',
          mark: '3', dotBg: '#FFFFFF', dotBorder: '#DCE7E1', dotInk: '#9AA5A0', line: 'transparent', titleInk: '#29483C',
        },
      ],

      onEditCard: async () => {
        const ok = await this.app.confirmDialog({
          title: 'Update payment method',
          body: 'In the live platform this opens the payment provider’s secure form. For the prototype we will attach a test card ending 4242.',
          confirmLabel: 'Attach test card',
          tone: 'primary',
        });
        if (!ok) return;
        await this.finance.updatePaymentMethod(this.vid, { last4: '4242', expiry: '09/29' });
        await this.load();
        this.app.toast('Payment method updated.', 'success');
      },
      onCancel: async () => {
        const ok = await this.app.confirmDialog({
          title: 'Cancel your subscription?',
          body: 'Paid listings are hidden when the current term ends. Free resources stay published, and you can resume any time.',
          confirmLabel: 'Cancel subscription',
        });
        if (!ok) return;
        await this.finance.cancelSubscription(this.vid);
        await this.load();
        this.app.toast('Subscription cancelled. Paid listings will be hidden at the end of the term.', 'info');
      },
      onResume: async () => {
        await this.finance.resumeSubscription(this.vid);
        await this.load();
        this.app.toast('Subscription resumed.', 'success');
      },
    };
  }
}

