class Component extends DCLogic {
  state = { confirmed: false, email: '', role: 'guest' };

  async componentDidMount() {
    const app = await __ulmImport('assets/js/app.js');
    await app.boot();
    this.app = app;
    const user = app.auth.currentUser();
