      confirmed,
      doneBody: isVendor
        ? 'Your email is confirmed. Your store is with an administrator for review.'
        : 'Your account is ready. Browse the catalogue and download your first resource.',
      nextHref: isVendor ? url('vendorPending') : url(nextParam || 'browse'),
      nextLabel: isVendor ? 'See my approval status' : 'Start browsing resources',
      onConfirm: () => {
        this.setState({ confirmed: true });
        this.app.toast('Email confirmed.', 'success');
      },
      onResend: () => this.app.toast('Confirmation email resent to ' + email + '.', 'info'),
    };
  }
}
